globalThis.ORDO_PROPERS_MONTHS ||= {}; globalThis.ORDO_PROPERS_MONTHS["2026-08"] = {"month":"2026-08","days":{"2026-08-01":{"date":"2026-08-01","title":"Ofício de Nossa Senhora no sábado","forms":[{"number":1,"title":"Sanctæ Mariæ Sabbato\tSimplex vide  [Commune/C10.txt]","winner":"Commune/C10.txt","rule":"vide C10\nSpecial Benedictio\nSpecial Lectio 3\nDoxology=Nat\nAntiphonas horas\nGloria\nSuffr=Spiritu;Ecclesiæ,Papa;;\nPrefatio=Maria=veneratione;\n\nex C10","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Martyrum Machabæorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>ratérna nos, Dómine, Mártyrum tuórum coróna lætíficet: quæ et fídei nostræ præbeat increménta virtútum; et multíplici nos suffrágio consolétur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei aos vossos servos, Senhor Deus, Vos suplicamos, o gozo da perpétua saúde da alma e do corpo, e que pela gloriosa intercessão da B. Maria, sempre Virgem, sejamos livres das tristezas dos tempos presentes e alcancemos o gozo da eterna alegria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Macabeus, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>azei, Senhor, que a vitória destes irmãos Mártires nos alegre, proporcionando à nossa fé aumento de vigor; e que nos sirva de consolação pela sua múltipla intercessão.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nAb inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nFui criada desde o princípio, antes de todos os séculos, e não deixarei de existir até à eternidade. Exerci perante Ele o meu ministério; e deste modo tenho habitação fixa em Sião. Ele deixa-me descansar na cidade santa e tenho poder em Jerusalém. Arraiguei-me em um povo glorioso, da parte do meu Deus e da sua herança, e permaneço na companhia dos santos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBenedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBendita e venerável sois vós, ó Virgem Maria, que fostes Mãe do Salvador, sem que a vossa pureza sofresse a mais leve ofensa.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Virgem Mãe de Deus, Aquele que nem todo o universo é capaz de conter, esteve encerrado, quando se fez homem, no vosso seio. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Depois de haverdes dado à luz, permanecestes Virgem Imaculada: Intercedei por nós, ó Mãe de Deus. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus às turbas, eis que uma mulher, elevando a voz no meio da multidão, Lhe disse: «Bem-aventurado o seio que Vos trouxe; bem-aventurados os peitos que Vos amamentaram!». E Jesus respondeu, dizendo: «Bem-aventurados, antes, aqueles que ouvem a palavra de Deus e a cumprem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:28 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:28; 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, Maria, cheia de graça: o Senhor é convosco: bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Martyrum Machabæorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ystéria tua, Dómine, pro sanctórum Mártyrum tuórum honóre, devóta mente tractémus: quibus et præsídium nobis crescat et gáudium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPela vossa misericórdia, Senhor, e pela intercessão da B. Maria, sempre Virgem, fazei que esta oblação nos assegure a prosperidade e a paz, agora e sempre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Macabeus, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue nós possamos, Senhor, celebrar com devoção os vossos sagrados mystérios em honra dos vossos Mártires, a fim de que sintamos aumentar o vosso auxílio e a nossa alegria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in veneratione beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventuradas as entranhas da Virgem Maria, que trouxeram encerrado o Filho do Pai Eterno.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Martyrum Machabæorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, quorum memóriam sacraménti participatióne recólimus, fidem quoque proficiéndo sectémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós, Senhor, alcançado o poderoso auxílio da nossa salvação, concedei-nos, Vos imploramos, que sejamos protegidos com o patrocínio da B. Maria, sempre Virgem, em cuja honra oferecemos à vossa majestade este sacrifício.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Macabeus, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>oncedei-nos, ó Deus omnipotente, que imitemos em nossos progressos na fé aquele cuja memória honrámos, participando deste sacramento.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-02":{"date":"2026-08-02","title":"X Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica X Post Pentecosten I. Augusti\tSemiduplex","winner":"Tempora/Pent10-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 54:17-20; 54:23\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>um clamárem ad Dóminum, exaudívit vocem meam, ab his, qui appropínquant mihi: et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 54:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExáudi, Deus, oratiónem meam, et ne despéxeris deprecatiónem meam: inténde mihi et exáudi me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>um clamárem ad Dóminum, exaudívit vocem meam, ab his, qui appropínquant mihi: et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 54:17-18; 54:20 54:23.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo invocasse o Senhor, ouviu Ele a minha voz e protegeu-me contra os que me combatem. Aquele que existia antes dos séculos e subsistirá eternamente humilhou-os. Depositai nas mãos do Senhor todas as preocupações, pois Ele vos sustentará.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 54:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nOuvi, Senhor, a minha oração e não desprezeis a minha humilde súplica: escutai-me, ouvi-me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo invocasse o Senhor, ouviu Ele a minha voz e protegeu-me contra os que me combatem. Aquele que existia antes dos séculos e subsistirá eternamente humilhou-os. Depositai nas mãos do Senhor todas as preocupações, pois Ele vos sustentará.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui omnipoténtiam tuam parcéndo máxime et miserándo maniféstas: multíplica super nos misericórdiam tuam; ut, ad tua promíssa curréntes, cœléstium bonórum fácias esse consórtes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que manifestais principalmente o vosso poder perdoando ao pecador e compadecendo-Vos das suas misérias, multiplicai sobre nós a abundância da vossa misericórdia, a fim de que, suspirando durante esta vida pelos bens que nos prometestes, nos tornemos participantes deles no céu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 12:2-11\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Scitis, quóniam, cum gentes essétis, ad simulácra muta prout ducebámini eúntes. Ideo notum vobisfacio, quod nemo in Spíritu Dei loquens, dicit anáthema Jesu. Et nemo potest dícere, Dóminus Jesus, nisi in Spíritu Sancto. Divisiónes vero gratiárum sunt, idem autem Spíritus. Et divisiónes ministratiónum sunt, idem autem Dóminus. Et divisiónes operatiónum sunt, idem vero Deus, qui operátur ómnia in ómnibus. Unicuíque autem datur manifestátio Spíritus ad utilitátem. Alii quidem per Spíritum datur sermo sapiéntiæ álii autem sermo sciéntiæ secúndum eúndem Spíritum: álteri fides in eódem Spíritu: álii grátia sanitátum in uno Spíritu: álii operátio virtútum, álii prophetía, álii discrétio spirítuum, álii génera linguárum, álii interpretátio sermónum. Hæc autem ómnia operátur unus atque idem Spíritus, dívidens síngulis, prout vult.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor. 12:2-11\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Recordai-vos de que, quando éreis pagãos, íeis aos ídolos mudos, sempre que vos conduziam. Ora, eu vos digo que ninguém, inspirado pelo Espírito de Deus, poderá anatematizar Jesus; nem ninguém, também, poderá dizer que Jesus é Senhor, senão inspirado pelo Espírito Santo. Na verdade, há diversas graças; porém o Espírito é o mesmo. Há diversos ministérios; porém o mesmo Senhor. Há diversidade de operações; porém não há senão um só Deus, que opera todas as coisas em nós. Os dons do Espírito Santo, que se manifestam em cada um, são para utilidade comum. A um é dado pelo Espírito o dom de falar com sabedoria; a outro é dado pelo mesmo Espírito o dom de falar com ciência; a um outro é dada a fé pelo mesmo Espírito; este recebe do mesmo Espírito a graça de curar os enfermos; aquele alcança o dom dos milagres; um outro o dom das profecias, aqueloutro o discernimento dos espíritos; este o dom de falar diversas línguas; e ainda aqueloutro o dom de as interpretar. É, porém, só um e o mesmo Espírito que produz todos este dons, distribuindo-os a cada um em particular como Lhe apraz.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:8; 16:2\u003c/I>\u003c/FONT>\u003cbr/>\nCustódi me, Dómine, ut pupíllam óculi: sub umbra alárum tuárum prótege me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> De vultu tuo judícium meum pródeat: óculi tui vídeant æquitátem.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion: et tibi reddétur votum in Jerúsalem. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:8, 2.\u003c/I>\u003c/FONT>\u003cbr/>\nGuardai-me, Senhor, como a pupila olhos: acolhei-me à sombra das vossas o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Que os vossos lábios pronunciem o meu juízo: e que os vossos olhos vejam a minha justiça. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Diante de Vós, Senhor, é conveniente cantar hinos em Sião: diante de Vós deve cada um cumprir os seus votos em Jerusalém. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 18:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus ad quosdam, qui in se confidébant tamquam justi et aspernabántur céteros, parábolam istam: Duo hómines ascendérunt in templum, ut orárent: unus pharisǽus, et alter publicánus. Pharisǽus stans, hæc apud se orábat: Deus, grátias ago tibi, quia non sum sicut céteri hóminum: raptóres, injústi, adúlteri: velut étiam hic publicánus. Jejúno bis in sábbato: décimas do ómnium, quæ possídeo. Et publicánus a longe stans nolébat nec óculos ad cœlum leváre: sed percutiébat pectus suum, dicens: Deus, propítius esto mihi peccatóri. Dico vobis: descéndit hic justificátus in domum suam ab illo: quia omnis qui se exáltat, humiliábitur: et qui se humíliat, exaltábitur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 18:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus esta parábola a uns certos que se presumiam justos e punham a confiança em si próprios, desprezando os outros: «dois homens subiram ao templo a orar, sendo um fariseu e o outro publicano. O fariseu, estando de pé, orava assim no seu íntimo: «Ő Deus, dou-Vos graças, porque não sou como os outros homens, que são ladrões, injustos e adúlteros, nem mesmo como este publicano; pois jejuo duas vezes na semana e pago o dízimo dos meus rendimentos». O publicano, ao contrário, conservando-se afastado, não ousava, sequer, levantar os olhos para o céu, e batia no peito, dizendo: «Meu Deus, tende piedade de mim, que sou um pobre pecador». Eu vos declaro, disse Jesus, que este voltou para sua casa justificado, mas não o outro; pois quem se eleva será humilhado, e quem se humilha será exaltado».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nAd te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós elevei a minha alma. O Deus, confio em Vós: não permitireis que e confundido e envergonhado: nem vencido meus inimigos; porquanto aqueles que em Vós confiam não serão confundidos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTibi, Dómine, sacrifícia dicáta reddántur: quæ sic ad honórem nóminis tui deferénda tribuísti, ut eadem remédia fíeri nostra præstáres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, é devida a homenagem destes sacrifícios, pois fostes Vós que permitindo-nos que os oferecêssemos em glória do vosso nome, os tornastes remédio das nossas almas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 50:21\u003c/I>\u003c/FONT>\u003cbr/>\nAcceptábis sacrifícium justítiæ, oblatiónes et holocáusta, super altáre tuum, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 50:21\u003c/I>\u003c/FONT>\u003cbr/>\nDignai-Vos, Senhor, aceitar sobre o vosso Altar o sacrifício da justiça, as ofertas e os holocaustos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, Dómine, Deus noster: ut, quos divínis reparáre non désinis sacraméntis, tuis non destítuas benígnus auxíliis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nVos suplicamos, ó Senhor, nosso Deus, não priveis do vosso auxílio àqueles a quem não cessais de alimentar com os divinos sacramentos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-03":{"date":"2026-08-03","title":"Féria da 10ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria secunda infra Hebdomadam X post Octavam Pentecostes I. Augusti\tFeria","winner":"Tempora/Pent10-1.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 54:17-20; 54:23\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>um clamárem ad Dóminum, exaudívit vocem meam, ab his, qui appropínquant mihi: et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 54:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExáudi, Deus, oratiónem meam, et ne despéxeris deprecatiónem meam: inténde mihi et exáudi me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>um clamárem ad Dóminum, exaudívit vocem meam, ab his, qui appropínquant mihi: et humiliávit eos, qui est ante sǽcula et manet in ætérnum: jacta cogitátum tuum in Dómino, et ipse te enútriet.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 54:17-18; 54:20 54:23.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo invocasse o Senhor, ouviu Ele a minha voz e protegeu-me contra os que me combatem. Aquele que existia antes dos séculos e subsistirá eternamente humilhou-os. Depositai nas mãos do Senhor todas as preocupações, pois Ele vos sustentará.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 54:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nOuvi, Senhor, a minha oração e não desprezeis a minha humilde súplica: escutai-me, ouvi-me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo invocasse o Senhor, ouviu Ele a minha voz e protegeu-me contra os que me combatem. Aquele que existia antes dos séculos e subsistirá eternamente humilhou-os. Depositai nas mãos do Senhor todas as preocupações, pois Ele vos sustentará.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui omnipoténtiam tuam parcéndo máxime et miserándo maniféstas: multíplica super nos misericórdiam tuam; ut, ad tua promíssa curréntes, cœléstium bonórum fácias esse consórtes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que manifestais principalmente o vosso poder perdoando ao pecador e compadecendo-Vos das suas misérias, multiplicai sobre nós a abundância da vossa misericórdia, a fim de que, suspirando durante esta vida pelos bens que nos prometestes, nos tornemos participantes deles no céu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 12:2-11\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Scitis, quóniam, cum gentes essétis, ad simulácra muta prout ducebámini eúntes. Ideo notum vobisfacio, quod nemo in Spíritu Dei loquens, dicit anáthema Jesu. Et nemo potest dícere, Dóminus Jesus, nisi in Spíritu Sancto. Divisiónes vero gratiárum sunt, idem autem Spíritus. Et divisiónes ministratiónum sunt, idem autem Dóminus. Et divisiónes operatiónum sunt, idem vero Deus, qui operátur ómnia in ómnibus. Unicuíque autem datur manifestátio Spíritus ad utilitátem. Alii quidem per Spíritum datur sermo sapiéntiæ álii autem sermo sciéntiæ secúndum eúndem Spíritum: álteri fides in eódem Spíritu: álii grátia sanitátum in uno Spíritu: álii operátio virtútum, álii prophetía, álii discrétio spirítuum, álii génera linguárum, álii interpretátio sermónum. Hæc autem ómnia operátur unus atque idem Spíritus, dívidens síngulis, prout vult.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor. 12:2-11\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Recordai-vos de que, quando éreis pagãos, íeis aos ídolos mudos, sempre que vos conduziam. Ora, eu vos digo que ninguém, inspirado pelo Espírito de Deus, poderá anatematizar Jesus; nem ninguém, também, poderá dizer que Jesus é Senhor, senão inspirado pelo Espírito Santo. Na verdade, há diversas graças; porém o Espírito é o mesmo. Há diversos ministérios; porém o mesmo Senhor. Há diversidade de operações; porém não há senão um só Deus, que opera todas as coisas em nós. Os dons do Espírito Santo, que se manifestam em cada um, são para utilidade comum. A um é dado pelo Espírito o dom de falar com sabedoria; a outro é dado pelo mesmo Espírito o dom de falar com ciência; a um outro é dada a fé pelo mesmo Espírito; este recebe do mesmo Espírito a graça de curar os enfermos; aquele alcança o dom dos milagres; um outro o dom das profecias, aqueloutro o discernimento dos espíritos; este o dom de falar diversas línguas; e ainda aqueloutro o dom de as interpretar. É, porém, só um e o mesmo Espírito que produz todos este dons, distribuindo-os a cada um em particular como Lhe apraz.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:8; 16:2\u003c/I>\u003c/FONT>\u003cbr/>\nCustódi me, Dómine, ut pupíllam óculi: sub umbra alárum tuárum prótege me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> De vultu tuo judícium meum pródeat: óculi tui vídeant æquitátem.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion: et tibi reddétur votum in Jerúsalem. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:8, 2.\u003c/I>\u003c/FONT>\u003cbr/>\nGuardai-me, Senhor, como a pupila olhos: acolhei-me à sombra das vossas o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Que os vossos lábios pronunciem o meu juízo: e que os vossos olhos vejam a minha justiça. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Diante de Vós, Senhor, é conveniente cantar hinos em Sião: diante de Vós deve cada um cumprir os seus votos em Jerusalém. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 18:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus ad quosdam, qui in se confidébant tamquam justi et aspernabántur céteros, parábolam istam: Duo hómines ascendérunt in templum, ut orárent: unus pharisǽus, et alter publicánus. Pharisǽus stans, hæc apud se orábat: Deus, grátias ago tibi, quia non sum sicut céteri hóminum: raptóres, injústi, adúlteri: velut étiam hic publicánus. Jejúno bis in sábbato: décimas do ómnium, quæ possídeo. Et publicánus a longe stans nolébat nec óculos ad cœlum leváre: sed percutiébat pectus suum, dicens: Deus, propítius esto mihi peccatóri. Dico vobis: descéndit hic justificátus in domum suam ab illo: quia omnis qui se exáltat, humiliábitur: et qui se humíliat, exaltábitur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 18:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus esta parábola a uns certos que se presumiam justos e punham a confiança em si próprios, desprezando os outros: «dois homens subiram ao templo a orar, sendo um fariseu e o outro publicano. O fariseu, estando de pé, orava assim no seu íntimo: «Ő Deus, dou-Vos graças, porque não sou como os outros homens, que são ladrões, injustos e adúlteros, nem mesmo como este publicano; pois jejuo duas vezes na semana e pago o dízimo dos meus rendimentos». O publicano, ao contrário, conservando-se afastado, não ousava, sequer, levantar os olhos para o céu, e batia no peito, dizendo: «Meu Deus, tende piedade de mim, que sou um pobre pecador». Eu vos declaro, disse Jesus, que este voltou para sua casa justificado, mas não o outro; pois quem se eleva será humilhado, e quem se humilha será exaltado».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nAd te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós elevei a minha alma. O Deus, confio em Vós: não permitireis que e confundido e envergonhado: nem vencido meus inimigos; porquanto aqueles que em Vós confiam não serão confundidos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTibi, Dómine, sacrifícia dicáta reddántur: quæ sic ad honórem nóminis tui deferénda tribuísti, ut eadem remédia fíeri nostra præstáres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, é devida a homenagem destes sacrifícios, pois fostes Vós que permitindo-nos que os oferecêssemos em glória do vosso nome, os tornastes remédio das nossas almas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 50:21\u003c/I>\u003c/FONT>\u003cbr/>\nAcceptábis sacrifícium justítiæ, oblatiónes et holocáusta, super altáre tuum, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 50:21\u003c/I>\u003c/FONT>\u003cbr/>\nDignai-Vos, Senhor, aceitar sobre o vosso Altar o sacrifício da justiça, as ofertas e os holocaustos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, Dómine, Deus noster: ut, quos divínis reparáre non désinis sacraméntis, tuis non destítuas benígnus auxíliis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nVos suplicamos, ó Senhor, nosso Deus, não priveis do vosso auxílio àqueles a quem não cessais de alimentar com os divinos sacramentos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-04":{"date":"2026-08-04","title":"São Domingos, confessor","forms":[{"number":1,"title":"S. Dominici Confessoris Duplex majus vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-04.txt","rule":"vide C5\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui Ecclésiam tuam beáti Domínici Confessóris tui illumináre dignátus es méritis et doctrínis: concéde; ut ejus intercessióne temporalibus non destituátur auxíliis, et spirituálibus semper profíciat increméntis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que Vos dignastes iluminar a vossa Igreja com os méritos e as lições do B. Domingos, vosso Confessor, concedei-nos pela sua intercessão que ela não seja privada dos auxílios temporais e que sempre tomem incremento os seus bens espirituais.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Timótheum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tim 4:1-8.\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prædica verbum, insta opportúne, importúne: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria coacervábunt sibi magístros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum ímple. Sóbrius esto. Ego enim jam délibor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo a Timóteo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tm 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimo: Conjuro-te diante de Deus e de Jesus Cristo, que há-de julgar vivos e mortos na sua vinda e no seu reino, a que pregues a palavra; instes oportuna e inoportunamente; repreendas; supliques; e ameaces com toda a paciência e doutrina; pois virá tempo em que não suportarão a sã doutrina, mas, indo ao sabor dos seus desejos, procurarão para si muitos mestres, que lhes preguem o que os ouvidos gostam de escutar, e fechem os ouvidos à verdade, para os abrirem às fábulas. Tu, porém, vigia, trabalha em tudo, cumpre o ministério de evangelista e desempenha o teu ministério. Sê sóbrio. Pois quanto a mim sou como uma vítima já aspergida para o sacrifício. O tempo da minha morte já se aproxima. Pelejei o bom combate; acabei a vida; permaneci na fé. Não me falta mais do que esperar a coroa da justiça, que me está reservada, a qual o Senhor, como justo juiz, me dará no grande dia: e não somente a mim, mas também àqueles que amam a sua vinda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Osee 14:6\u003c/I>\u003c/FONT>\u003cbr/>\nJustus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Para publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Oz 14:6\u003c/I>\u003c/FONT>\u003cbr/>\nO justo germinará, como o lírio, e florescerá eternamente na presença do Senhor. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha verdade e a minha misericórdia estarão com ele, e, por virtude do meu nome, será exaltado o seu poder. \u003cFONT SIZE='1' COLOR=\"red\">T. P. Aleluia.\u003c/FONT>\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nMúnera tibi, Dómine, dicáta sanctífica: ut, méritis beáti Domínici Confessóris tui, nobis profíciant ad medélam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSantificai, Senhor, os dons que Vos são apresentados, a fim de que, pelos méritos do B. Domingos, vosso Confessor, sirvam de remédio, às nossas almas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nO servo fiel e prudente é destinado pelo Senhor para distribuir oportunamente a cada um na sua família a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde, quǽsumus, omnípotens Deus: ut, qui peccatórum nostrórum póndere prémimur, beáti Domínici Confessóris tui patrocínio sublevémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei-nos, Deus omnipotente. Vos rogamos, que, estando oprimidos sob o peso dos nossos pecados, sejamos livres deles, pelo patrocínio do B. Domingos, vosso Confessor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-05":{"date":"2026-08-05","title":"Dedicação de Nossa Senhora das Neves","forms":[{"number":1,"title":"S. Mariæ ad Nives Duplex majus ex Commune Beatae Mariae Virginis [Commune/C11.txt]","winner":"Sancti/08-05.txt","rule":"ex C11;\nGloria\nCredoDA\nPrefatio=Maria=Festivitate;\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei aos vossos servos, Senhor Deus, Vos suplicamos, o gozo da perpétua saúde da alma e do corpo, e que pela gloriosa intercessão da B. Maria, sempre Virgem, sejamos livres das tristezas dos tempos presentes e alcancemos o gozo da eterna alegria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nAb inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nFui criada desde o princípio, antes de todos os séculos, e não deixarei de existir até à eternidade. Exerci perante Ele o meu ministério; e deste modo tenho habitação fixa em Sião. Ele deixa-me descansar na cidade santa e tenho poder em Jerusalém. Arraiguei-me em um povo glorioso, da parte do meu Deus e da sua herança, e permaneço na companhia dos santos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBenedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBendita e venerável sois vós, ó Virgem Maria, que fostes Mãe do Salvador, sem que a vossa pureza sofresse a mais leve ofensa.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Virgem Mãe de Deus, Aquele que nem todo o universo é capaz de conter, esteve encerrado, quando se fez homem, no vosso seio. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Depois de haverdes dado à luz, permanecestes Virgem Imaculada: Intercedei por nós, ó Mãe de Deus. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus às turbas, eis que uma mulher, elevando a voz no meio da multidão, Lhe disse: «Bem-aventurado o seio que Vos trouxe; bem-aventurados os peitos que Vos amamentaram!». E Jesus respondeu, dizendo: «Bem-aventurados, antes, aqueles que ouvem a palavra de Deus e a cumprem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:28 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:28; 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, Maria, cheia de graça: o Senhor é convosco: bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPela vossa misericórdia, Senhor, e pela intercessão da B. Maria, sempre Virgem, fazei que esta oblação nos assegure a prosperidade e a paz, agora e sempre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in Festivitate beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventuradas as entranhas da Virgem Maria, que trouxeram encerrado o Filho do Pai Eterno.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós, Senhor, alcançado o poderoso auxílio da nossa salvação, concedei-nos, Vos imploramos, que sejamos protegidos com o patrocínio da B. Maria, sempre Virgem, em cuja honra oferecemos à vossa majestade este sacrifício.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-06":{"date":"2026-08-06","title":"Transfiguração do Senhor","forms":[{"number":1,"title":"In Transfiguratione Domini Nostri Jesu Christi Duplex II classis","winner":"Sancti/08-06.txt","rule":"Gloria\nCredo\nPrefatio=Communis\nPrefatio=Nat\nFestum Domini\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 76:19\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>lluxérunt coruscatiónes tuæ orbi terræ: commóta est et contrémuit terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nQuam dilécta tabernácula tua, Dómine virtútum! Concupíscit, et déficit ánima mea in átria Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>lluxérunt coruscatiónes tuæ orbi terræ: commóta est et contrémuit terra.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 76:19\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s vossos relâmpagos iluminaram o globo terrestre: moveu-se a terra e tremeu.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nComo são amáveis os vossos tabernáculos, ó Senhor dos exércitos! Minha alma suspira ardentemente pelos átrios do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s vossos relâmpagos iluminaram o globo terrestre: moveu-se a terra e tremeu.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui fídei sacraménta in Unigéniti tui gloriósa Transfiguratióne patrum testimónio roborásti, et adoptiónem filiórum perféctam, voce delápsa in nube lúcida, mirabíliter præsignásti: concéde propítius; ut ipsíus Regis glóriæ nos coherédes effícias, et ejúsdem glóriæ tríbuas esse consórtes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Xysti II Papæ, Felicissimi et Agapiti Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nos concédis sanctórum Mártyrum tuórum Xysti Felicíssimi et Agapíti  natalítia cólere: da nobis in ætérna beatitúdine de eórum societáte gaudére.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que na gloriosa Transfiguração de vosso Filho Unigénito confirmastes os méritos da fé pelo testemunho dos patriarcas, e que pela voz saída da nuvem iluminada proclamastes admiravelmente a perfeita adopção que de nós fizestes como vossos filhos, concedei-nos propício a graça de nos tornarmos co-herdeiros do Rei da glória e de mais tarde sermos participantes desta mesma glória.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Sixto, Felicíssimo e Agapito, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que nos permitistes a graça de celebrarmos o nascimento no céu dos vossos Santos Mártires Sixto, Felicíssimo e Agapito, concedei-nos ainda a graça de gozarmos na sua companhia a bem-aventurança eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Petri Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Petri 1:16-19\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimi: Non doctas fábulas secúti notam fecimus vobis Dómini nostri Jesu Christi virtútem et præséntiam: sed speculatores facti illíus magnitudinis. Accipiens enim a Deo Patre honórem et glóriam, voce delapsa ad eum hujuscemodi a magnifica glória: Hic est Fílius meus diléctus, in quo mihi complacui, ipsum audíte. Et hanc vocem nos audivimus de cœlo allatam, cum essemus cum ipso in monte sancto. Et habémus firmiórem propheticum sermónem: cui bene facitis attendentes, quasi lucérnæ lucénti in caliginóso loco, donec dies elucescat et lucifer oriátur in córdibus vestris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Pedro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Pe 1:16-19\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimos: Não foi servindo-nos de fábulas engenhosas que vos fizemos conhecer o poder e a vinda de Nosso Senhor Jesus Cristo, mas depois de havermos sido espectadores da sua majestade. Com efeito, Ele recebeu de Deus Pai honra e glória, quando da glória magnífica desceu sobre Ele esta voz: «Este é o meu Filho muito amado, em quem pus as minhas complacências; ouvi-O». Nós também ouvimos esta voz, vinda do céu, quando estávamos com Ele, na montanha sagrada. E consideramos a palavra profética como firmíssima, à qual fazeis bem em atender, como se fora uma lâmpada em um lugar escuro, até que o dia brilhe e que a estrela da manhã nasça nos nossos corações!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3; 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nSpeciósus forma præ fíliis hóminum: diffúsa est grátia in lábiis tuis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Eructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 7:26\u003c/I>\u003c/FONT>\u003cbr/>\nCandor est lucis ætérnæ, spéculum sine mácula, et imágo bonitátis illíus. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3; 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nSois o mais belo dos filhos dos homens: a graça espalhou-se nos vossos lábios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Meu coração exprimiu uma palavra excelente: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 7:26\u003c/I>\u003c/FONT>\u003cbr/>\nEste é o esplendor da luz eterna, o espelho sem mancha de Deus e a imagem da sua bondade! Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 17:1-9\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Assúmpsit Jesus Petrum, et Jacóbum, et Joánnem fratrem ejus, et duxit illos in montem excélsum seórsum: et transfigurátus est ante eos. Et resplénduit fácies ejus sicut sol: vestiménta autem ejus facta sunt alba sicut nix. Et ecce, apparuérunt illis Moyses et Elías cum eo loquéntes. Respóndens autem Petrus, dixit ad Jesum: Dómine, bonum est nos hic esse: si vis, faciámus hic tria tabernácula, tibi unum, Móysi unum et Elíæ unum. Adhuc eo loquénte, ecce, nubes lúcida obumbrávit eos. Et ecce vox de nube, dicens: Hic est Fílius meus diléctus, in quo mihi bene complácui: ipsum audíte. Et audiéntes discípuli, cecidérunt in fáciem suam, et timuérunt valde. Et accéssit Jesus, et tétigit eos, dixítque eis: Surgite, et nolíte timére. Levántes autem óculos suos, néminem vidérunt nisi solum Jesum. Et descendéntibus illis de monte, præcépit eis Jesus, dicens: Némini dixéritis visiónem, donec Fílius hóminis a mórtuis resúrgat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt. 17:1-9\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus levou consigo Pedro, Tiago e João e conduziu-os a um monte alto e separado, transfigurando-se ante eles: seu rosto resplandecia, como o sol, e os seus vestidos tornaram-se brancos, como a neve! E Moisés e Elias apareceram, conversando com Jesus. Então, Pedro disse a Jesus: «Senhor, é tão bom estar aqui!... Se quereis, façamos aqui três tendas: uma para Vós, outra para Moisés e outra para Elias!». Ainda ele falava, eis que uma nuvem brilhante os envolveu, saindo do seio dela uma voz, que dizia: «Este é o meu Filho muito amado, em quem pus as minhas complacências; ouvi-O». Havendo escutado a voz, os discípulos caíram com o rosto no chão e ficaram atemorizados. Mas Jesus tocou-os e disse-lhes: «Levantai-vos; não vos amedronteis». Então, erguendo os olhos, já nada viram senão só Jesus. Desceram do monte, dando-lhes Jesus esta ordem: «Não conteis a ninguém esta visão até que o Filho do homem ressuscite dos mortos».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:3\u003c/I>\u003c/FONT>\u003cbr/>\nGlória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi, allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:3\u003c/I>\u003c/FONT>\u003cbr/>\nA glória e as riquezas estão na sua casa; a sua justiça subsistirá para sempre. Aleluia.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nObláta, quǽsumus, Dómine, múnera gloriósa Unigéniti tui Transfiguratióne sanctífica: nosque a peccatórum máculis, splendóribus ipsíus illustratiónis emúnda.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Xysti II Papæ, Felicissimi et Agapiti Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>únera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSantificai, Senhor, pela gloriosa Transfiguração do vosso Filho Unigénito, Vos pedimos, as oblatas que Vos apresentamos; e pelos esplendores da sua glorificação purificai-nos das manchas dos nossos pecados.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Sixto, Felicíssimo e Agapito, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os oferecemos, Senhor, estes dons da nossa devoção; e, em atenção aos merecimentos dos vossos justos, dignai-Vos aceitá-los, e pela vossa misericórdia fazei que nos sejam salutares.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 17:9\u003c/I>\u003c/FONT>\u003cbr/>\nVisiónem, quam vidístis, némini dixéritis, donec a mórtuis resúrgat Fílius hóminis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 17:9\u003c/I>\u003c/FONT>\u003cbr/>\nNão conteis a ninguém esta visão até que o Filho do homem ressuscite dos mortos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, omnípotens Deus: ut sacrosáncta Fílii tui Transfiguratiónis mystéria, quæ sollemni celebrámus offício, purificáta mentis intellegéntia consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Xysti II Papæ, Felicissimi et Agapiti Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis Xysto, Felicíssimo et Agapíto; ut, quod ore contíngimus, pura mente capiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente, Vos suplicamos, fazei que possamos gozar com a alma purificada de todas as manchas os sacrossantos mystérios da Transfiguração do vosso Filho, que celebrámos solenemente neste ofício.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Sixto, Felicíssimo e Agapito, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, por intercessão dos vossos santos Mártires Sixto, Felicíssimo e Agapito, dignai-Vos conceder-nos a graça de guardarmos com o coração sempre puro o que a nossa boca agora recebeu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-07":{"date":"2026-08-07","title":"São Caetano, confessor","forms":[{"number":1,"title":"S. Cajetani Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-07.txt","rule":"vide C5;\n9 lectiones\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beáto Cajetáno Confessóri tuo apostólicam vivéndi formam imitári tribuísti: da nobis, ejus intercessióne et exémplo, in te semper confídere et sola cæléstia desideráre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Donati Episcopi et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, tuórum glória sacerdótum: præsta, quǽsumus, ut sancti Martyris tui et Epíscopi Donáti, cujus festa gérimus, sentiámus auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que concedestes ao B. Caetano, vosso Confessor, a graça de imitar o modo de vida dos Apóstolos, permiti-nos, pela sua intercessão e exemplo, que sempre depositemos em Vós a nossa confiança e somente aspiremos aos bens celestiais.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Donato\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que sois a glória dos vossos sacerdotes, permiti, Vos suplicamos, que experimentemos o auxílio do vosso Santo Mártir e Bispo Donato, cuja festa celebramos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 6:24-33\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Nemo potest duóbus dóminis servíre: aut enim unum ódio habébit, et álterum díliget: aut unum sustinébit, et álterum contémnet. Non potéstis Deo servíre et mammónæ. Ideo dico vobis, ne sollíciti sitis ánimæ vestræ, quid manducétis, neque córpori vestro, quid induámini. Nonne ánima plus est quam esca: et corpus plus quam vestiméntum? Respícite volatília cœli, quóniam non serunt neque metunt neque cóngregant in hórrea: et Pater vester cœléstis pascit illa. Nonne vos magis pluris estis illis? Quis autem vestrum cógitans potest adjícere ad statúram suam cúbitum unum? Et de vestiménto quid sollíciti estis? Consideráte lília agri, quómodo crescunt: non labórant neque nent. Dico autem vobis, quóniam nec Sálomon in omni glória sua coopértus est sicut unum ex istis. Si autem fænum agri, quod hódie est et cras in clíbanum míttitur, Deus sic vestit: quanto magis vos módicæ fídei? Nolíte ergo sollíciti esse, dicéntes: Quid manducábimus aut quid bibémus aut quo operiémur? Hæc enim ómnia gentes inquírunt. Scit enim Pater vester, quia his ómnibus indigétis. Quǽrite ergo primum regnum Dei et justítiam ejus: et hæc ómnia adjiciéntur vobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 6:24-33\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Ninguém pode servir a dois senhores, pois ou há-de odiar um e amar o outro, ou respeitar este e desprezar aquele. Não podeis servir a Deus e às riquezas. Eis porque digo: não vos inquieteis pelas cousas da vossa vida, se tereis o que comer; nem do vosso corpo, se tereis o que vestir. Porventura não é a vida mais do que o alimento e o corpo mais do que o vestido? Reparai nas aves do céu: nem semeiam, nem ceifam, nem arrecadam nos celeiros; contudo o Pai celestial sustenta-as. Acaso não valeis mais do que elas? Qual de vós será capaz, ainda que empregue todas as diligências, de acrescentar um côvado à sua altura? E, quanto ao vestir, porque vos inquietais? Reparai como os lírios dos campos crescem! Eles não trabalham, nem fiam; contudo nem Salomão, apesar de toda sua magnificência, teve um vestido como eles. Ora, se Deus veste assim as ervas dos campos, que hoje existem e amanhã serão lançadas no fogo, quanto mais terá cuidado de vós, homens de pouca fé! Não vos inquieteis, pois, dizendo: «Que havemos de comer e de beber; e como nos vestiremos?». Os pagãos é que têm cuidados com estas cousas. Vosso Pai celestial sabe bem aquilo de que careceis. Procurai primeiramente o reino de Deus e a sua justiça, e todas estas cousas vos serão dadas».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Donati Episcopi et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, Dómine: ut sancti Martyris tu iet Episcopi Donati intercessióne, quem ad laudem nóminis tui dicátis munéribus honorámus, piæ nobis fructus devotiónis accréscat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Deus omnipotente, Vos suplicamos, fazei que esta oblata da nossa humildade em honra dos vossos Santos Vos seja agradável e nos purifique ao mesmo tempo o corpo e a alma.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Donato\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos suplicamos, fazei que pela intercessão do vosso Santo Mártir e Bispo Donato, a quem honramos oferecendo estes dons em louvor do vosso nome, sintamos aumentar em nós os frutos de uma devoção piedosa.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Donati Episcopi et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>mnípotens et miséricors Deus, qui nos sacramentórum tuórum et partícipes éfficis et minístros: præsta, quǽsumus; ut, intercedénte beáto Donáto Mártyre tuo atque Pontífice, ejúsdem proficiámus et fídei consórtio et digno servítio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido o alimento celestial, ó Deus omnipotente, Vos suplicamos, fazei que pela intercessão do B. Caetano, vosso Confessor, sejamos fortalecidos contra todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Donato\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>mnipotente e misericordioso Deus, que nos tornastes participantes e ministros dos vossos sacramentos, concedei-nos, Vos imploramos, que pela intercessão do B. Donato, vosso Mártir e Pontífice, não só gozemos a comparticipação da sua fé, mas como ele Vos sirvamos dignamente.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-08":{"date":"2026-08-08","title":"São João Maria Vianney, confessor","forms":[{"number":1,"title":"S. Joannis Mariæ Vianney Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-09.txt","rule":"vide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens et miséricors Deus, qui sanctum Joánnem Maríam pastoráli stúdio et jugi oratiónis ac pœniténtiæ ardóre mirábilem effecísti: da, quǽsumus; ut, ejus exémplo et intercessióne, ánimas fratrum lucrári Christo, et cum eis ætérnam glóriam cónsequi valeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Cyriaci, Largi et Smaragdi Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nos ánnua sanctórum Mártyrum tuórum Cyríaci, Largi et Smarágdi sollemnitáte lætíficas: concéde propítius; ut, quorum gaudémus méritis, accendámur exémplis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOmnipotente e misericordioso Deus, que, pelo seu zelo pastoral e pelo seu ardor na oração e na penitência, tornastes admirável o B. João Maria, concedei-nos, Vos suplicamos, que, seguindo o seu exemplo e pela sua intercessão, possamos conquistar para Cristo as almas dos nossos irmãos e com eles alcançar a glória eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Ciríaco e Outros\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que nos alegrais com a festa anual dos vossos Santos Mártires Ciríaco, Largo e Esmaragdo, concedei-nos propício que, honrando o seu nascimento no céu, imitemos também a coragem do seu martírio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Cyriaci, Largi et Smaragdi Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ccépta sit in conspéctu tuo, Dómine, nostra devótio: et eórum nobis fiat supplicatióne salutáris, pro quorum sollemnitáte defértur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Ciríaco e Outros\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>eja recebida na vossa presença, Senhor, esta nossa devota oferta; e fazei que, pela súplica daqueles em cuja honra Vo-la apresentamos, ela nos seja salutar.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Cyriaci, Largi et Smaragdi Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedéntibus sanctis Martýribus tuis Cyríaco, Largo et Smarágdo, sentiámus efféctum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPelos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Ciríaco e Outros\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedéntibus sanctis Martýribus tuis Cyríaco, Largo et Smarágdo, sentiámus efféctum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-09":{"date":"2026-08-09","title":"XI Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XI Post Pentecosten II. Augusti\tSemiduplex","winner":"Tempora/Pent11-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 67:6-7; 67:36\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 67:2\u003c/I>\u003c/FONT>\u003cbr/>\nExsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 67:6 67:7 67:36\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus está na sua santa morada: Deus dará morada na sua casa àqueles que possuem o mesmo espírito: Ele dará ao seu povo fortaleza e constância.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 67:2\u003c/I>\u003c/FONT>\u003cbr/>\nErga-se Deus e sejam dispersos os seus inimigos: Que aqueles que o odeiam fujam da sua presença.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus está na sua santa morada: Deus dará morada na sua casa àqueles que possuem o mesmo espírito: Ele dará ao seu povo fortaleza e constância.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui, abundántia pietátis tuæ, et mérita súpplicum excédis et vota: effúnde super nos misericórdiam tuam; ut dimíttas quæ consciéntia métuit, et adícias quod orátio non præsúmit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDeus omnipotente e sempiterno, que pela abundância da vossa bondade excedeis os méritos e os desejos dos suplicantes, espalhai a vossa misericórdia sobre nós, de modo que nos sejam perdoados aqueles castigos, que a nossa consciência teme, e nos sejam concedidas aquelas graças, que não ousamos pedir:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Notum vobis fácio Evangélium, quod prædicávi vobis, quod et accepístis, in quo et statis, per quod et salvámini: qua ratione prædicáverim vobis, si tenétis, nisi frustra credidístis. Trádidi enim vobis in primis, quod et accépi: quóniam Christus mortuus est pro peccátis nostris secúndum Scriptúras: et quia sepúltus est, et quia resurréxit tértia die secúndum Scriptúras: et quia visus est Cephæ, et post hoc úndecim. Deinde visus est plus quam quingéntis frátribus simul, ex quibus multi manent usque adhuc, quidam autem dormiérunt. Deinde visus est Jacóbo, deinde Apóstolis ómnibus: novíssime autem ómnium tamquam abortívo, visus est et mihi. Ego enim sum mínimus Apostolórum, qui non sum dignus vocári Apóstolus, quóniam persecútus sum Ecclésiam Dei. Grátia autem Dei sum id quod sum, et grátia ejus in me vácua non fuit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor. 15:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Chamo a vossa atenção para o Evangelho que já vos preguei e recebestes. Nele permanecereis firmes, sendo por ele que sereis salvos, se porventura o cumprirdes tal como vo-lo anunciei; pois, se não fora assim, teríeis abraçado a fé inutilmente. Em primeiro lugar, ensinei-vos o que também aprendi, isto é: Que Cristo morreu por causa dos nossos pecados, segundo as Escrituras; que foi sepultado e ressuscitou ao terceiro dia, segundo as mesmas Escrituras; que apareceu a Cefas e seguidamente aos outros Onze Apóstolos; que, depois, foi visto por mais de quinhentos irmãos, que estavam reunidos, alguns dos quais estão vivos e outros já morreram; que, igualmente, foi visto por Tiago e logo pelos outros Apóstolos. Finalmente, depois dos outros, foi visto por mim, que sou o mais imperfeito de todos. Sim; sou o mínimo dos Apóstolos, assim como sou indigno de ser chamado Apóstolo, pois fui perseguidor da Igreja de Deus. Mas, pela graça de Deus, sou o que sou, e a sua graça não ficou estéril em mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 27:7 27:1\u003c/I>\u003c/FONT>\u003cbr/>\nIn Deo sperávit cor meum, et adjútus sum: et reflóruit caro mea, et ex voluntáte mea confitébor illi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ad te, Dómine, clamávi: Deus meus, ne síleas, ne discédas a me. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 80:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExsultáte Deo, adjutóri nostro, jubiláte Deo Jacob: súmite psalmum jucúndum cum cíthara. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 27:7\u003c/I>\u003c/FONT>\u003cbr/>\nO meu coração confiou em Deus, que veio em meu socorro. Então a minha carne remoçou. Eis porque louvarei o Senhor com todo o coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Clamei por Vós, Senhor! Meu Deus, não fecheis os ouvidos à minha voz, nem Vos afasteis de mim. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 80:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Exultai de alegria em Deus, que é o nosso protector: Cantai hinos em honra de Deus de Jacob: Tocai em tom alegre o saltério e a cítara. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Marcum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 7:31-37\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Exiens Jesus de fínibus Tyri, venit per Sidónem ad mare Galilǽæ, inter médios fines Decapóleos. Et addúcunt ei surdum et mutum, et deprecabántur eum, ut impónat illi manum. Et apprehéndens eum de turba seórsum, misit dígitos suos in aurículas ejus: et éxspuens, tétigit linguam ejus: et suspíciens in cœlum, ingémuit, et ait illi: Ephphetha, quod est adaperíre. Et statim apértæ sunt aures ejus, et solútum est vínculum linguæ ejus, et loquebátur recte. Et præcépit illis, ne cui dícerent. Quanto autem eis præcipiébat, tanto magis plus prædicábant: et eo ámplius admirabántur, dicéntes: Bene ómnia fecit: et surdos fecit audíre et mutos loqui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Marcos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 7:31-37\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo saindo Jesus do território de Tiro, veio por Sidónia, através da Decápole, até ao mar da Galileia. Então, apresentaram-lhe um surdo-mudo e suplicaram-Lhe que pusesse as mãos sobre ele. Jesus, separando-o da multidão, pôs-lhe os dedos nos ouvidos e saliva na língua. Depois, erguendo os olhos ao céu, deu um suspiro e disse: «Ephpheta», isto é, abre-te! E logo se abriram os ouvidos deste homem e se partiu a prisão da sua língua, falando distintamente. Então Jesus impôs-lhes que não dissessem a ninguém o que se passara; mas, quanto mais os proibia, mais o publicavam; e, cheios de admiração, diziam: Ele fez bem tudo, fez ouvir os surdos e falar os mudos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 29:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me: Dómine, clamávi ad te, et sanásti me.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 29:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExaltar-Vos-ei, Senhor, porque me atendestes e não deixastes que meus inimigos escarnecem de mim. Clamei por Vós, Senhor, e curaste-me!\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRéspice, Dómine, quǽsumus, nostram propítius servitútem: ut, quod offérimus, sit tibi munus accéptum, et sit nostræ fragilitátis subsidium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos, Senhor, Vos suplicamos, olhar propício para a nossa homenagem, a fim de que a nossa oferta Vos seja agradável e sirva de auxílio para a nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 3:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nHónora Dóminum de tua substántia, et de prímitiis frugum tuárum: et implebúntur hórrea tua saturitáte, et vino torculária redundábunt.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 3:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nHonrai o Senhor, oferecendo-Lhe os vossos bens e as primícias dos vossos frutos. Então os vossos celeiros ficarão cheios de trigo e os vossos lagares trasbordarão de vinho.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSentiámus, quǽsumus, Dómine, tui perceptióne sacraménti, subsídium mentis et córporis: ut, in utróque salváti, cæléstis remédii plenitúdine gloriémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, Vos suplicamos, que, pela recepção do vosso sacramento, sintamos o vosso conforto na alma e no corpo, a fim de que, salvando-se ambos, possamos gozar na glória a plenitude deste remédio celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-10":{"date":"2026-08-10","title":"São Lourenço, diácono e mártir, mártir","forms":[{"number":1,"title":"S. Laurentii Martyris Duplex II classis ex Commune Unius Martyris non Pontificis (Missa In virtute) [Commune/C2a.txt]","winner":"Sancti/08-10.txt","rule":"Gloria\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 95:6\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onféssio et pulchritúdo in conspéctu ejus: sánctitas et magnificéntia in sanctificatióne ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 95:1\u003c/I>\u003c/FONT>\u003cbr/>\nCantáte Dómino cánticum novum: cantáte Dómino, omnis terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onféssio et pulchritúdo in conspéctu ejus: sánctitas et magnificéntia in sanctificatióne ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 95:6\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>odeiam-no a glória e a majestade: e no seu santuário reluzem a santidade e a magnificência.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 95:1\u003c/I>\u003c/FONT>\u003cbr/>\nCantai em honra do Senhor um hino novo: que toda a terra cante hinos ao Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>odeiam-no a glória e a majestade: e no seu santuário reluzem a santidade e a magnificência.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDa nobis, quǽsumus, omnípotens Deus: vitiórum nostrorum flammas exstínguere; qui beáto Lauréntio tribuísti tormentórum suórum incéndia superáre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente, que permitistes que o B. Lourenço triunfasse das chamas do seu suplício, concedei-nos a graça, Vos suplicamos, de extinguirdes as chamas dos nossos vícios.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 9:6-10.\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Qui parce séminat, parce et metet: et qui séminat in benedictiónibus, de benedictiónibus et metet. Unusquísque prout destinávit in corde suo, non ex tristítia aut ex necessitáte: hilárem enim datórem díligit Deus. Potens est autem Deus omnem grátiam abundáre fácere in vobis, ut, in ómnibus semper omnem sufficiéntiam habéntes, abundétis in omne opus bonum, sicut scriptum est: Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi. Qui autem admínistrat semen seminánti: et panem ad manducándum præstábit, et multiplicábit semen vestrum, et augébit increménta frugum justítiæ vestræ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 9:6-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Aquele que semeia pouco, colherá pouco também; e aquele que semeia com abundância, colherá também com abundância. Que cada um dê segundo o que tiver resolvido no seu coração; mas não com tristeza, nem com constrangimento: pois Deus ama aquele que dá com alegria. Deus é assaz poderoso para vos cumular de todas as graças, a fim de que, possuindo, sempre, em todas as coisas, aquilo que vos é necessário, tenhais com abundância, para praticardes todas as espécies de boas obras, segundo o que está escrito: «Distribuiu liberalmente os seus bens pelos pobres: a sua justiça subsistirá em todos os séculos dos séculos». Com efeito, aquele que dá a semente ao semeador dar-vos-á também o pão para comida, multiplicará a vossa semente e dará incremento aos frutos da vossa justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 16:3.\u003c/I>\u003c/FONT>\u003cbr/>\nProbásti, Dómine, cor meum, et visitásti nocte.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Igne me examinásti, et non est invénta in me iníquitas.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Levíta Lauréntius bonum opus operátus est: qui per signum crucis cœcos illuminávit. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 16:3\u003c/I>\u003c/FONT>\u003cbr/>\nExperimentastes o meu coração e visitaste-lo durante a noite.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Experimentastes-me com o fogo e não se encontrou em mim a iniquidade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O Levita Lourenço praticou uma boa acção: pois restituiu a vista aos cegos com o sinal da Santa Cruz. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 12:24-26\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Amen, amen, dico vobis, nisi granum fruménti cadens in terram, mórtuum fúerit, ipsum solum manet: si autem mórtuum fúerit, multum fructum affert. Qui amat ánimam suam, perdet eam: et qui odit ánimam suam in hoc mundo, in vitam ætérnam custódit eam. Si quis mihi mínistrat, me sequátur: et ubi sum ego, illic et miníster meus erit. Si quis mihi ministráverit, honorificábit eum Pater meus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 12:24-26\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Se o grão de trigo, caindo na terra, não morrer, permanece estéril; mas, se morrer, dará muito fruto. Aquele que ama a sua vida perdê-la-á; mas aquele que aborrece a sua vida neste mundo conservá-la-á para a vida eterna. Se alguém me serve, siga-me; e onde eu estiver lá estará também o meu servo. Se alguém me servir, meu Pai o honrará».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 95:6\u003c/I>\u003c/FONT>\u003cbr/>\nConféssio et pulchritúdo in conspéctu ejus: sánctitas, et magnificéntia in sanctificatióne ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 95:6\u003c/I>\u003c/FONT>\u003cbr/>\nRodeiam-no a glória e a majestade: e no seu santuário reluzem a santidade e a magnificência.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccipe, quǽsumus, Dómine, múnera dignánter obláta: et, beáti Lauréntii suffragántibus méritis, ad nostræ salútis auxílium proveníre concéde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRecebei, Senhor, Vos suplicamos, os dons que reverentemente Vos oferecemos, e, pelo sufrágio dos méritos do B. Lourenço, permiti que nos sirvam de auxílio para a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 12:26\u003c/I>\u003c/FONT>\u003cbr/>\nQui mihi mínistrat, me sequátur: et ubi ego sum, illic et miníster meus erit.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 12:26\u003c/I>\u003c/FONT>\u003cbr/>\nSe alguém me serve, siga-me; e onde eu estiver lá estará também o meu servo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSacro múnere satiáti, súpplices te, Dómine, deprecámur: ut, quod débitæ servitútis celebrámus offício, intercedénte beáto Lauréntio Mártyre tuo, salvatiónis tuæ sentiámus augméntum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSaciados com este sacrossanto dom, humildemente Vos rogamos pela intercessão do B. Lourenço, vosso Mártir, que, celebrando este ofício em reconhecimento da nossa escravidão, alcancemos cada vez mais os efeitos da vossa Redenção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-11":{"date":"2026-08-11","title":"Féria da 11ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria tertia infra Hebdomadam XI post Octavam Pentecostes II. Augusti\tFeria","winner":"Tempora/Pent11-2.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 67:6-7; 67:36\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 67:2\u003c/I>\u003c/FONT>\u003cbr/>\nExsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 67:6 67:7 67:36\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus está na sua santa morada: Deus dará morada na sua casa àqueles que possuem o mesmo espírito: Ele dará ao seu povo fortaleza e constância.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 67:2\u003c/I>\u003c/FONT>\u003cbr/>\nErga-se Deus e sejam dispersos os seus inimigos: Que aqueles que o odeiam fujam da sua presença.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus está na sua santa morada: Deus dará morada na sua casa àqueles que possuem o mesmo espírito: Ele dará ao seu povo fortaleza e constância.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui, abundántia pietátis tuæ, et mérita súpplicum excédis et vota: effúnde super nos misericórdiam tuam; ut dimíttas quæ consciéntia métuit, et adícias quod orátio non præsúmit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Tiburtii et Susannæ Virginis, Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctórum Martyrum tuórum Tiburtii et Susánnæ nos, Dómine, fóveant continuáta præsídia: quia non désinis propítius intuéri; quos tálibus auxíliis concésseris adjuvári.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDeus omnipotente e sempiterno, que pela abundância da vossa bondade excedeis os méritos e os desejos dos suplicantes, espalhai a vossa misericórdia sobre nós, de modo que nos sejam perdoados aqueles castigos, que a nossa consciência teme, e nos sejam concedidas aquelas graças, que não ousamos pedir:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Tibúrcio e Susana, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ermiti, Senhor, que nos favoreça o contínuo auxílio dos vossos Santos Mártires Tibúrcio e Susana, pois não podeis deixar de acolher propiciamente aqueles a quem concedeis o socorro de tal protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Notum vobis fácio Evangélium, quod prædicávi vobis, quod et accepístis, in quo et statis, per quod et salvámini: qua ratione prædicáverim vobis, si tenétis, nisi frustra credidístis. Trádidi enim vobis in primis, quod et accépi: quóniam Christus mortuus est pro peccátis nostris secúndum Scriptúras: et quia sepúltus est, et quia resurréxit tértia die secúndum Scriptúras: et quia visus est Cephæ, et post hoc úndecim. Deinde visus est plus quam quingéntis frátribus simul, ex quibus multi manent usque adhuc, quidam autem dormiérunt. Deinde visus est Jacóbo, deinde Apóstolis ómnibus: novíssime autem ómnium tamquam abortívo, visus est et mihi. Ego enim sum mínimus Apostolórum, qui non sum dignus vocári Apóstolus, quóniam persecútus sum Ecclésiam Dei. Grátia autem Dei sum id quod sum, et grátia ejus in me vácua non fuit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor. 15:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Chamo a vossa atenção para o Evangelho que já vos preguei e recebestes. Nele permanecereis firmes, sendo por ele que sereis salvos, se porventura o cumprirdes tal como vo-lo anunciei; pois, se não fora assim, teríeis abraçado a fé inutilmente. Em primeiro lugar, ensinei-vos o que também aprendi, isto é: Que Cristo morreu por causa dos nossos pecados, segundo as Escrituras; que foi sepultado e ressuscitou ao terceiro dia, segundo as mesmas Escrituras; que apareceu a Cefas e seguidamente aos outros Onze Apóstolos; que, depois, foi visto por mais de quinhentos irmãos, que estavam reunidos, alguns dos quais estão vivos e outros já morreram; que, igualmente, foi visto por Tiago e logo pelos outros Apóstolos. Finalmente, depois dos outros, foi visto por mim, que sou o mais imperfeito de todos. Sim; sou o mínimo dos Apóstolos, assim como sou indigno de ser chamado Apóstolo, pois fui perseguidor da Igreja de Deus. Mas, pela graça de Deus, sou o que sou, e a sua graça não ficou estéril em mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 27:7 27:1\u003c/I>\u003c/FONT>\u003cbr/>\nIn Deo sperávit cor meum, et adjútus sum: et reflóruit caro mea, et ex voluntáte mea confitébor illi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ad te, Dómine, clamávi: Deus meus, ne síleas, ne discédas a me. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 80:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExsultáte Deo, adjutóri nostro, jubiláte Deo Jacob: súmite psalmum jucúndum cum cíthara. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 27:7\u003c/I>\u003c/FONT>\u003cbr/>\nO meu coração confiou em Deus, que veio em meu socorro. Então a minha carne remoçou. Eis porque louvarei o Senhor com todo o coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Clamei por Vós, Senhor! Meu Deus, não fecheis os ouvidos à minha voz, nem Vos afasteis de mim. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 80:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Exultai de alegria em Deus, que é o nosso protector: Cantai hinos em honra de Deus de Jacob: Tocai em tom alegre o saltério e a cítara. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Marcum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 7:31-37\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Exiens Jesus de fínibus Tyri, venit per Sidónem ad mare Galilǽæ, inter médios fines Decapóleos. Et addúcunt ei surdum et mutum, et deprecabántur eum, ut impónat illi manum. Et apprehéndens eum de turba seórsum, misit dígitos suos in aurículas ejus: et éxspuens, tétigit linguam ejus: et suspíciens in cœlum, ingémuit, et ait illi: Ephphetha, quod est adaperíre. Et statim apértæ sunt aures ejus, et solútum est vínculum linguæ ejus, et loquebátur recte. Et præcépit illis, ne cui dícerent. Quanto autem eis præcipiébat, tanto magis plus prædicábant: et eo ámplius admirabántur, dicéntes: Bene ómnia fecit: et surdos fecit audíre et mutos loqui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Marcos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 7:31-37\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo saindo Jesus do território de Tiro, veio por Sidónia, através da Decápole, até ao mar da Galileia. Então, apresentaram-lhe um surdo-mudo e suplicaram-Lhe que pusesse as mãos sobre ele. Jesus, separando-o da multidão, pôs-lhe os dedos nos ouvidos e saliva na língua. Depois, erguendo os olhos ao céu, deu um suspiro e disse: «Ephpheta», isto é, abre-te! E logo se abriram os ouvidos deste homem e se partiu a prisão da sua língua, falando distintamente. Então Jesus impôs-lhes que não dissessem a ninguém o que se passara; mas, quanto mais os proibia, mais o publicavam; e, cheios de admiração, diziam: Ele fez bem tudo, fez ouvir os surdos e falar os mudos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 29:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me: Dómine, clamávi ad te, et sanásti me.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 29:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExaltar-Vos-ei, Senhor, porque me atendestes e não deixastes que meus inimigos escarnecem de mim. Clamei por Vós, Senhor, e curaste-me!\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRéspice, Dómine, quǽsumus, nostram propítius servitútem: ut, quod offérimus, sit tibi munus accéptum, et sit nostræ fragilitátis subsidium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Tiburtii et Susannæ Virginis, Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>désto, Dómine, précibus pópuli tui, adésto munéribus: ut, quæ sacris sunt obláta mystériis, tuórum tibi pláceant intercessióne Sanctórum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos, Senhor, Vos suplicamos, olhar propício para a nossa homenagem, a fim de que a nossa oferta Vos seja agradável e sirva de auxílio para a nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Tibúrcio e Susana, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>tendei, Senhor, às preces do vosso povo e recebei as suas ofertas, a fim de que, pela intercessão dos vossos Santos Mártires, a oblação destes mystérios Vos seja agradável.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 3:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nHónora Dóminum de tua substántia, et de prímitiis frugum tuárum: et implebúntur hórrea tua saturitáte, et vino torculária redundábunt.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 3:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nHonrai o Senhor, oferecendo-Lhe os vossos bens e as primícias dos vossos frutos. Então os vossos celeiros ficarão cheios de trigo e os vossos lagares trasbordarão de vinho.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSentiámus, quǽsumus, Dómine, tui perceptióne sacraménti, subsídium mentis et córporis: ut, in utróque salváti, cæléstis remédii plenitúdine gloriémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Tiburtii et Susannæ Virginis, Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úmpsimus, Dómine, pignus redemptiónis ætérnæ: quod sit nobis, quǽsumus, interveniéntibus sanctis Martýribus tuis, vitæ præséntis auxílium páriter et futúræ.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, Vos suplicamos, que, pela recepção do vosso sacramento, sintamos o vosso conforto na alma e no corpo, a fim de que, salvando-se ambos, possamos gozar na glória a plenitude deste remédio celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Tibúrcio e Susana, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebemos, Senhor, o penhor da eterna redenção; e permiti, pela intercessão dos vossos Santos Mártires, que nos sirva de auxílio, tanto na vida presente, como na futura.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-12":{"date":"2026-08-12","title":"Santa Clara, virgem","forms":[{"number":1,"title":"S. Claræ Virginis Duplex vide Commune Unius Virginis tantum (Missa Dilexisti) [Commune/C6a.txt]","winner":"Sancti/08-12.txt","rule":"vide C6a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>mastes a justiça e odiastes a iniquidade; pelo que ungiu-vos o Senhor, vosso Deus, com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>mastes a justiça e odiastes a iniquidade; pelo que ungiu-vos o Senhor, vosso Deus, com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nExáudi nos, Deus, salutáris noster: ut sicut de beátæ Claræ Vírginis tuæ festivitáte gaudémus; ita piæ devotiónis erudiámur afféctu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOuvi-nos, ó Deus, nosso salvador, a fim de que, assim como nos alegramos com a festa da vossa B. Virgem Clara, assim também consigamos os afectos de uma pia devoção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 10:17-18; 11:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 10:17-18; 11:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Aquele que se gloria, glorie-se no Senhor; pois não é aprovado o que se louva a si mesmo, mas aquele a quem Deus recomenda. Queira Deus que possais suportar um pouco ainda a minha loucura; mas suportai-me ainda, pois estou zeloso de vós da parte do zelo de Deus. Com efeito, desposei-vos com o único esposo, para vos apresentar a Cristo como virgem pura.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nAdducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai com beleza e com majestade; ide gozar a vitória e reinai.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da verdade, da mansidão e da justiça, a vossa dextra praticará maravilhas! Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nApós ela, serão apresentadas virgens ao Rei: as suas companheiras serão introduzidas no meio da alegria. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines íllæ, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a dez virgens que, empunhando suas lâmpadas, saíram ao encontro do esposo e da esposa. Porém, cinco destas virgens eram loucas e as outras cinco eram prudentes. Ora, as cinco loucas, empunhando suas lâmpadas, não levaram azeite. Ao contrário, as prudentes tomaram azeite em seus vasos para suas lâmpadas. Como o esposo se demorasse em chegar, tiveram sono e dormiram. Quando era meia-noite, ouviu-se um clamor dizer: «Eis que chega o esposo; ide ao seu encontro». Então todas estas virgens se ergueram e prepararam as suas lâmpadas. As loucas disseram às prudentes: «Dai-nos do vosso azeite, porque as nossas lâmpadas apagam-se». As prudentes responderam-lhes: «Não, porque pode suceder que, como a vós, nos falte o azeite; ide antes aos que o vendem, e comprai-o». Ora, enquanto elas foram comprar o azeite, veio o esposo. Então, as que estavam preparadas entraram com ele para as bodas; e fechou-se a porta. Por fim vieram as outras virgens, e disseram: «Senhor, senhor, abri-nos a porta». Ele respondeu: «Na verdade vos digo: não vos conheço. Vigiai, pois, visto que não sabeis nem o dia nem a hora».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:10\u003c/I>\u003c/FONT>\u003cbr/>\nFíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:10\u003c/I>\u003c/FONT>\u003cbr/>\nAs filhas dos reis formam a vossa corte de glória: a própria rainha está colocada à vossa direita, envergando um vestido de ouro, recamado da mais rica variedade.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:4-6\u003c/I>\u003c/FONT>\u003cbr/>\nQuinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:4; 25:6\u003c/I>\u003c/FONT>\u003cbr/>\nAs cinco virgens prudentes levaram azeite em seus vasos para suas lâmpadas. Ora, no meio da noite, ouviu-se este clamor: «Eis que chega o esposo; comparecei diante de Cristo, vosso Senhor».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo Vós, Senhor, saciado a vossa família com vossos dons sagrados, dignai-Vos favorecer-nos sempre com a intercessão daquela cuja festa celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-13":{"date":"2026-08-13","title":"Féria da 11ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria quinta infra Hebdomadam XI post Octavam Pentecostes II. Augusti\tFeria","winner":"Tempora/Pent11-4.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 67:6-7; 67:36\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 67:2\u003c/I>\u003c/FONT>\u003cbr/>\nExsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 67:6 67:7 67:36\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus está na sua santa morada: Deus dará morada na sua casa àqueles que possuem o mesmo espírito: Ele dará ao seu povo fortaleza e constância.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 67:2\u003c/I>\u003c/FONT>\u003cbr/>\nErga-se Deus e sejam dispersos os seus inimigos: Que aqueles que o odeiam fujam da sua presença.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus está na sua santa morada: Deus dará morada na sua casa àqueles que possuem o mesmo espírito: Ele dará ao seu povo fortaleza e constância.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui, abundántia pietátis tuæ, et mérita súpplicum excédis et vota: effúnde super nos misericórdiam tuam; ut dimíttas quæ consciéntia métuit, et adícias quod orátio non præsúmit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Hippolyti et Cassiani Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>a, quǽsumus, omnípotens Deus: ut beatórum Mártyrum tuórum Hippolýti et Cassiáni veneránda sollémnitas, et devotiónem nobis áugeat et salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDeus omnipotente e sempiterno, que pela abundância da vossa bondade excedeis os méritos e os desejos dos suplicantes, espalhai a vossa misericórdia sobre nós, de modo que nos sejam perdoados aqueles castigos, que a nossa consciência teme, e nos sejam concedidas aquelas graças, que não ousamos pedir:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Hipólito e Cassiano, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>oncedei-nos, ó Deus omnipotente, Vos rogamos, que a veneranda festa dos vossos B. B. Mártires Hipólito e Cassiano aumente a nossa piedade e nos faça alcançar a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Notum vobis fácio Evangélium, quod prædicávi vobis, quod et accepístis, in quo et statis, per quod et salvámini: qua ratione prædicáverim vobis, si tenétis, nisi frustra credidístis. Trádidi enim vobis in primis, quod et accépi: quóniam Christus mortuus est pro peccátis nostris secúndum Scriptúras: et quia sepúltus est, et quia resurréxit tértia die secúndum Scriptúras: et quia visus est Cephæ, et post hoc úndecim. Deinde visus est plus quam quingéntis frátribus simul, ex quibus multi manent usque adhuc, quidam autem dormiérunt. Deinde visus est Jacóbo, deinde Apóstolis ómnibus: novíssime autem ómnium tamquam abortívo, visus est et mihi. Ego enim sum mínimus Apostolórum, qui non sum dignus vocári Apóstolus, quóniam persecútus sum Ecclésiam Dei. Grátia autem Dei sum id quod sum, et grátia ejus in me vácua non fuit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor. 15:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Chamo a vossa atenção para o Evangelho que já vos preguei e recebestes. Nele permanecereis firmes, sendo por ele que sereis salvos, se porventura o cumprirdes tal como vo-lo anunciei; pois, se não fora assim, teríeis abraçado a fé inutilmente. Em primeiro lugar, ensinei-vos o que também aprendi, isto é: Que Cristo morreu por causa dos nossos pecados, segundo as Escrituras; que foi sepultado e ressuscitou ao terceiro dia, segundo as mesmas Escrituras; que apareceu a Cefas e seguidamente aos outros Onze Apóstolos; que, depois, foi visto por mais de quinhentos irmãos, que estavam reunidos, alguns dos quais estão vivos e outros já morreram; que, igualmente, foi visto por Tiago e logo pelos outros Apóstolos. Finalmente, depois dos outros, foi visto por mim, que sou o mais imperfeito de todos. Sim; sou o mínimo dos Apóstolos, assim como sou indigno de ser chamado Apóstolo, pois fui perseguidor da Igreja de Deus. Mas, pela graça de Deus, sou o que sou, e a sua graça não ficou estéril em mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 27:7 27:1\u003c/I>\u003c/FONT>\u003cbr/>\nIn Deo sperávit cor meum, et adjútus sum: et reflóruit caro mea, et ex voluntáte mea confitébor illi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ad te, Dómine, clamávi: Deus meus, ne síleas, ne discédas a me. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 80:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExsultáte Deo, adjutóri nostro, jubiláte Deo Jacob: súmite psalmum jucúndum cum cíthara. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 27:7\u003c/I>\u003c/FONT>\u003cbr/>\nO meu coração confiou em Deus, que veio em meu socorro. Então a minha carne remoçou. Eis porque louvarei o Senhor com todo o coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Clamei por Vós, Senhor! Meu Deus, não fecheis os ouvidos à minha voz, nem Vos afasteis de mim. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 80:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Exultai de alegria em Deus, que é o nosso protector: Cantai hinos em honra de Deus de Jacob: Tocai em tom alegre o saltério e a cítara. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Marcum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 7:31-37\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Exiens Jesus de fínibus Tyri, venit per Sidónem ad mare Galilǽæ, inter médios fines Decapóleos. Et addúcunt ei surdum et mutum, et deprecabántur eum, ut impónat illi manum. Et apprehéndens eum de turba seórsum, misit dígitos suos in aurículas ejus: et éxspuens, tétigit linguam ejus: et suspíciens in cœlum, ingémuit, et ait illi: Ephphetha, quod est adaperíre. Et statim apértæ sunt aures ejus, et solútum est vínculum linguæ ejus, et loquebátur recte. Et præcépit illis, ne cui dícerent. Quanto autem eis præcipiébat, tanto magis plus prædicábant: et eo ámplius admirabántur, dicéntes: Bene ómnia fecit: et surdos fecit audíre et mutos loqui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Marcos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 7:31-37\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo saindo Jesus do território de Tiro, veio por Sidónia, através da Decápole, até ao mar da Galileia. Então, apresentaram-lhe um surdo-mudo e suplicaram-Lhe que pusesse as mãos sobre ele. Jesus, separando-o da multidão, pôs-lhe os dedos nos ouvidos e saliva na língua. Depois, erguendo os olhos ao céu, deu um suspiro e disse: «Ephpheta», isto é, abre-te! E logo se abriram os ouvidos deste homem e se partiu a prisão da sua língua, falando distintamente. Então Jesus impôs-lhes que não dissessem a ninguém o que se passara; mas, quanto mais os proibia, mais o publicavam; e, cheios de admiração, diziam: Ele fez bem tudo, fez ouvir os surdos e falar os mudos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 29:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me: Dómine, clamávi ad te, et sanásti me.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 29:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nExaltar-Vos-ei, Senhor, porque me atendestes e não deixastes que meus inimigos escarnecem de mim. Clamei por Vós, Senhor, e curaste-me!\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRéspice, Dómine, quǽsumus, nostram propítius servitútem: ut, quod offérimus, sit tibi munus accéptum, et sit nostræ fragilitátis subsidium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Hippolyti et Cassiani Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>éspice, Dómine, múnera pópuli tui, Sanctórum festivitáte votíva: et tuæ testificátio veritátis nobis profíciat ad salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos, Senhor, Vos suplicamos, olhar propício para a nossa homenagem, a fim de que a nossa oferta Vos seja agradável e sirva de auxílio para a nossa fraqueza.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Hipólito e Cassiano, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignai-Vos olhar, Senhor, para as oblatas que o vosso povo Vos oferece nesta festa dos vossos Santos, e fazei que o testemunho, por eles dado à vossa verdade, nos seja útil para a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 3:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nHónora Dóminum de tua substántia, et de prímitiis frugum tuárum: et implebúntur hórrea tua saturitáte, et vino torculária redundábunt.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 3:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nHonrai o Senhor, oferecendo-Lhe os vossos bens e as primícias dos vossos frutos. Então os vossos celeiros ficarão cheios de trigo e os vossos lagares trasbordarão de vinho.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSentiámus, quǽsumus, Dómine, tui perceptióne sacraménti, subsídium mentis et córporis: ut, in utróque salváti, cæléstis remédii plenitúdine gloriémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Hippolyti et Cassiani Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acramentórum tuórum, Dómine, commúnio sumpta nos salvet: et in tuæ veritátis luce confírmet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, Vos suplicamos, que, pela recepção do vosso sacramento, sintamos o vosso conforto na alma e no corpo, a fim de que, salvando-se ambos, possamos gozar na glória a plenitude deste remédio celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S.S. Hipólito e Cassiano, Mártires\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue a comunhão dos vossos sacramentos, que recebemos, Senhor, nos alcance a salvação e nos confirme na profissão da vossa doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-14":{"date":"2026-08-14","title":"Vigília da Assunção de Nossa Senhora","forms":[{"number":1,"title":"In Vigilia Assumptionis B.M.V. Duplex II classis","winner":"Sancti/08-14.txt","rule":"no Gloria\nPrefatio=Communis\nSuffragium=Spiritu;;\n\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:13; 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:13; 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odos os poderosos da terra implorarão os vossos olhares: após ela, serão apresentadas virgens ao Rei: as suas companheiras serão apresentadas ao Rei com grande alegria e júbilo. \u003cFONT SIZE='1' COLOR=\"red\">T. P. Aleluia, aleluia.\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma palavra excelente: Consagro ao Rei as minhas obras!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odos os poderosos da terra implorarão os vossos olhares: após ela, serão apresentadas virgens ao Rei: as suas companheiras serão apresentadas ao Rei com grande alegria e júbilo. \u003cFONT SIZE='1' COLOR=\"red\">T. P. Aleluia, aleluia.\u003c/FONT>\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui virginálem aulam beátæ Maríæ, in qua habitáres, elígere dignátus es: da, quǽsumus; ut, sua nos defensióne munitos, jucúndos fácias suæ interésse festivitáti:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Eusebii Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nos beáti Eusébii Confessóris tui ánnua solemnitáte lætíficas: concéde propítius; ut cujus natalítia cólimus, étiam actiónes imitémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que Vos dignastes escolher por morada o seio virginal da Bem-aventurada Virgem Maria, fazei, como Vos pedimos, que, ao abrigo de sua protecção possamos assistir com alegria à sua festa.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Eusébio, Confessor\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que nos alegrais pela solenidade anual do bem-aventurado Eusébio, vosso Confessor, fazei, em vossa bondade, que honrando o nascimento desse Santo no céu e praticando seus exemplos, possamos subir a Vós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:23-31\u003c/I>\u003c/FONT>\u003cbr/>\nEgo quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:23-31\u003c/I>\u003c/FONT>\u003cbr/>\nEu produzi, como a vinha, flores de suave odor, e as minhas flores são frutos de honra e de honestidade. Eu sou a mãe do amor puro, do temor, da ciência e da esperança santa. Em mim existe toda a graça do caminho e da verdade; em mim existe toda a esperança da vida e da virtude. Vinde a mim, ó vós, que me desejais com ardor, e saciai-vos com meus frutos; pois o meu espírito é mais doce do que o mel e a minha herança excede em doçura o próprio favo de mel! Minha memória permanecerá nas gerações de todos os séculos. Aqueles que me comerem terão ainda fome; e aqueles que me beberem terão ainda sede. Aqueles que me escutam não serão confundidos; aqueles que se orientarem em mim não pecarão; e aqueles que me tornarem conhecida alcançarão a vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBenedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBendita e venerável sois, ó Virgem Maria, que fostes Mãe do Salvador sem a vossa pureza sofrer a mais leve mancha.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Virgem, Mãe de Deus, Aquele a quem todo o universo é incapaz de conter, esteve encerrado no vosso seio, quando se fez homem.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus às turbas, eis que uma mulher, elevando a voz no meio da multidão, Lhe disse: «Bem-aventurado o seio que Vos trouxe; bem-aventurados os peitos que Vos amamentaram!». E Jesus respondeu, dizendo: «Bem-aventurados, antes, aqueles que ouvem a palavra de Deus e a cumprem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta es, Virgo María, quæ ómnium portásti Creatórem: genuísti qui te fecit, et in ætérnum pérmanes Virgo.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventurada sois, ó Virgem Maria, pois trouxestes no vosso seio o Criador de todas as coisas. Gerastes Aquele que vos criou; e permanecereis eternamente Virgem.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nMúnera nostra, Dómine, apud cleméntiam tuam Dei Genetrícis comméndet orátio: quam idcírco de præsénti sǽculo transtulísti; ut pro peccátis nostris apud te fiduciáliter intercédat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Eusebii Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>audis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue as nossas ofertas, Senhor, tenham como recomendação junto da vossa clemência as súplicas da Mãe de Deus, a qual arrebatastes deste mundo para interceder com confiança pelos nossos pecados junto de Vós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Eusébio, Confessor\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventuradas as entranhas da B. V. Maria, que trouxeram encerrado o Filho do Pai Eterno.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde, miséricors Deus, fragilitáti nostræ præsídium: ut, qui sanctæ Dei Genetrícis festivitátem prævenímus; intercessiónis ejus auxílio a nostris iniquitátibus resurgámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Eusebii Confessoris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus de misericórdia, dignai-Vos vir em auxílio da nossa fragilidade, a fim de que, antecipando a festividade da Santa Mãe de Deus, possamos, com o auxílio da sua intercessão, ressuscitar das nossas iniquidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Eusébio, Confessor\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-15":{"date":"2026-08-15","title":"Assunção da Bem-aventurada Virgem Maria","forms":[{"number":1,"title":"In Assumptione Beatæ Mariæ Virginis Duplex I classis ex Commune Beatae Mariae Virginis [Commune/C11.txt]","winner":"Sancti/08-15.txt","rule":"Gloria\nCredo\nPrefatio=Maria=Assumptióne;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ap 12:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ignum magnum appáruit in cœlo: múlier amicta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 97:1\u003c/I>\u003c/FONT>\u003cbr/>\nCantáte Dómino cánticum novum: quóniam mirabília fecit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ignum magnum appáruit in cœlo: múlier amicta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 12:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>m grande prodígio apareceu no céu: uma mulher revestida com o Sol, tendo a lua sob os seus pés e na cabeça uma coroa com doze estrelas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 97:1\u003c/I>\u003c/FONT>\u003cbr/>\nCantai ao Senhor um cântico novo, pois Ele operou maravilhas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>m grande prodígio apareceu no céu: uma mulher revestida com o Sol, tendo a lua sob os seus pés e na cabeça uma coroa com doze estrelas.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui Immaculátam Vírginem Maríam, Fílii tui Genetrícem, córpore et ánima ad cœléstem glóriam assumpsísti: concéde, quǽsumus; ut, ad superna semper inténti, ipsíus glóriæ mereámur esse consórtes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOmnipotente e sempiterno Deus, que elevastes em corpo e alma até à glória celestial a Imaculada Virgem Maria, Mãe de vosso Filho, concedei-nos, Vos suplicamos, que, tendo nós sempre presente ao nosso espírito os dons celestiais, mereçamos tornar-nos participantes da mesma glória.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Judith\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Judith 13, 22-25; 15:10\u003c/I>\u003c/FONT>\u003cbr/>\nBenedíxit te Dóminus in virtúte sua, quia per te ad níhilum redégit inimícos nostros. Benedícta es tu, fília, a Dómino Deo excelso, præ ómnibus muliéribus super terram. Benedíctus Dóminus, qui creávit cœlum et terram, qui te diréxit in vúlnera cápitis príncipis inimicórum nostrórum; quia hódie nomen tuum ita magnificávit, ut non recédat laus tua de ore hóminum, qui mémores fúerint virtútis Dómini in ætérnum, pro quibus non pepercísti ánimæ tuæ propter angústias et tribulatiónem géneris tui, sed subvenísti ruínæ ante conspéctum Dei nostri. Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro de Judite.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jdt 13, 22-25; 15:10\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoou-te o Senhor com seu poder e por ti aniquilou os nossos inimigos. Bendita és tu, ó filha, entre todas as mulheres, ante o Senhor Deus Altíssimo, e bendito é o Senhor, que criou o céu e a terra e dirigiu os teus passos para cortares a cabeça do chefe dos nossos inimigos; pois, hoje, de tal modo Ele engrandeceu o teu nome que nunca mais o teu elogio se apagará na boca dos que eternamente se lembrarem do poder do Senhor, por amor dos quais não poupaste a tua vida, ao ver as angústias e tribulações do teu povo, antes impediste a sua ruína na presença do nosso Deus. Tu és a glória de Jerusalém, a alegria de Israel e a honra do nosso povo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:11-12; 44:14\u003c/I>\u003c/FONT>\u003cbr/>\nAudi, fília, et vide, et inclína aurem tuam, et concupíscet rex pulchritúdinem tuam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Tota decóra ingréditur fília regis, textúræ áureæ sunt amíctus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Assumpta est María in cœlum: gaudet exércitus Angelórum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:11-12; 44:14\u003c/I>\u003c/FONT>\u003cbr/>\nOuvi, ó filha, vede e aplicai os vossos ouvidos: e o Rei cobiçará a vossa formosura!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A filha do Rei entra toda gloriosa no seu palácio: os seus vestidos são tecidos de brocado de ouro. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Maria foi elevada ao céu em corpo e alma: alegra-se o exército dos Anjos. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:41-50\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Repléta est Spíritu Sancto Elísabeth et exclamávit voce magna, et dixit: Benedícta tu inter mulíeres, et benedíctus fructus ventris tui. Et unde hoc mihi ut véniat mater Dómini mei ad me? Ecce enim ut facta est vox salutatiónis tuæ in áuribus meis, exsultávit in gáudio infans in útero meo. Et beáta, quæ credidísti, quóniam perficiéntur ea, quæ dicta sunt tibi a Dómino. Et ait María: Magníficat ánima mea Dóminum; et exsultávit spíritus meus in Deo salutári meo; quia respéxit humilitátem ancíllæ suæ, ecce enim ex hoc beátam me dicent omnes generatiónes. Quia fecit mihi magna qui potens est, et sanctum nomen ejus, et misericórdia ejus a progénie in progénies timéntibus eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:41-50\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo: Isabel ficou cheia do Espírito Santo e exclamou, em voz alta: «Bendita sois vós entre as mulheres e bendito é o fruto do vosso ventre. E donde me vem a mim que a mãe do meu Senhor venha até mim? Porquanto, desde que a voz da vossa saudação chegou a meus ouvidos, o meu filho exultou de alegria no meu seio! Bem-aventurada sois, porque acreditastes que se há-de cumprir o que vos foi dito da parte do Senhor». Maria disse então: «Minha alma glorifica o Senhor e o meu espírito se alegra em Deus, meu Salvador, que se dignou olhar para a humildade da sua serva; por isso, eis que todas as gerações me chamarão bem-aventurada. Pois Aquele que é omnipotente, e o seu nome é santo, operou em mim maravilhas, e a sua misericórdia multiplicar-se-á de geração em geração sobre os que O temem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gen 3:15\u003c/I>\u003c/FONT>\u003cbr/>\nInimicítias ponam inter te et mulíerem, et semen tuum et semen illíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gn 3:15\u003c/I>\u003c/FONT>\u003cbr/>\nPorei inimizades entre ti e a Mulher, e entre a tua prole e a sua Prole.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAscéndat ad te, Dómine, nostræ devotiónis oblátio, et, beatíssima Vírgine María in cœlum assumpta intercedénte, corda nostra, caritátis igne succénsa, ad te júgiter ádspirent.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAscenda até Vós, Senhor, a oblação da nossa piedade; e, por intercessão da beatíssima Virgem Maria, elevada ao céu em corpo e alma, permiti que, abrasados nossos corações no fogo da caridade, continuamente por Vós aspirem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in Assumptióne beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:48-49\u003c/I>\u003c/FONT>\u003cbr/>\nBeátam me dicent omnes generatiónes, quia fecit mihi magna qui potens est.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:48-49\u003c/I>\u003c/FONT>\u003cbr/>\nChamar-me-ão Bem-aventurada todas as gerações, pois Aquele, que é omnipotente, operou em mim maravilhas.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, salutáribus sacraméntis: da, quǽsumus; ut, méritis et intercessióne beátæ Vírginis Maríæ in cœlum assúmptæ, ad resurrectiónis glóriam perducámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo recebido, Senhor, os vossos salutares sacramentos, concedei-nos, Vos suplicamos, que, pelos méritos e intercessão da Bem-aventurada Virgem Maria, elevada ao céu em corpo e alma, sejamos conduzidos à glória da ressurreição.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-16":{"date":"2026-08-16","title":"XII Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XII Post Pentecosten III. Augusti\tSemiduplex","winner":"Tempora/Pent12-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 69:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, in adjutórium meum inténde: Dómine, ad adjuvándum me festína: confundántur et revereántur inimíci mei, qui quærunt ánimam meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 69:4\u003c/I>\u003c/FONT>\u003cbr/>\nAvertántur retrórsum et erubéscant: qui cógitant mihi mala.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, in adjutórium meum inténde: Dómine, ad adjuvándum me festína: confundántur et revereántur inimíci mei, qui quærunt ánimam meam.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 69:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, vinde em meu auxílio. Apressai-Vos, Senhor, em socorrer-me! Que fiquem confundidos e envergonhados os meus inimigos, que procuram tirar-me a vida.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 69:4\u003c/I>\u003c/FONT>\u003cbr/>\nFujam de mim, cheios de vergonha aqueles que querem a minha perda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, vinde em meu auxílio. Apressai-Vos, Senhor, em socorrer-me! Que fiquem confundidos e envergonhados os meus inimigos, que procuram tirar-me a vida.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens et miséricors Deus, de cujus múnere venit, ut tibi a fidélibus tuis digne et laudabíliter serviátur: tríbue, quǽsumus, nobis; ut ad promissiónes tuas sine offensióne currámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Joachim Confessoris, Patris B. M. V.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui præ ómnibus Sanctis tuis beátum Jóachim Genetrícis Fílii tui patrem esse voluísti: concéde, quǽsumus; ut, cujus festa venerámur, ejus quoque perpétuo patrocínia sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e misericordioso, a quem os fiéis são devedores da felicidade de Vos prestarem culto agradável e digno, concedei-nos a graça, Vos suplicamos, de procurarmos sempre sem qualquer obstáculo os bens que nos prometestes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Joaquim, Pai da Nossa Senhora\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que, de preferência a todos vossos Santos, quisestes que o B. Joaquim fosse o Pai da Mãe de vosso Filho, concedei-nos, Vos suplicamos, que experimentemos o perpétuo patrocínio daquele cuja festa celebramos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 3:4-9\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Fidúciam talem habémus per Christum ad Deum: non quod sufficiéntes simus cogitáre áliquid a nobis, quasi ex nobis: sed sufficiéntia nostra ex Deo est: qui et idóneos nos fecit minístros novi testaménti: non líttera, sed spíritu: líttera enim occídit, spíritus autem vivíficat. Quod si ministrátio mortis, lítteris deformáta in lapídibus, fuit in glória; ita ut non possent inténdere fili Israël in fáciem Moysi, propter glóriam vultus ejus, quæ evacuátur: quómodo non magis ministrátio Spíritus erit in glória? Nam si ministrátio damnatiónis glória est multo magis abúndat ministérium justítiæ in glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor. 3:4-9\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Devemos ter toda a confiança em Deus por Cristo, pois não somos capazes nem dum pensamento que tenha origem em nós, mas tudo nos vem de Deus. Com efeito, foi Ele quem nos tornou aptos para sermos ministros da Nova Aliança, não pela letra, mas pelo Espírito; pois a letra mata, mas o Espírito vivifica. Ora, se o ministério da morte, gravado em letras sobre as pedras, foi acompanhado de tal glória que os filhos de Israel não podiam fitar o rosto de Moisés, por causa do brilho que irradiava dele \u003cFONT SIZE='1' COLOR=\"red\">o qual, contudo, era passageiro\u003c/FONT>, como não será mais glorioso o ministério do Espírito? Se o ministério da condenação foi glorioso, incomparavelmente mais glorioso será o ministério que confere a justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 33:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícam Dóminum in omni témpore: semper laus ejus in ore meo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Dómino laudábitur ánima mea: áudiant mansuéti, et læténtur. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 87:2\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, Deus salútis meæ, in die clamávi et nocte coram te. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 33:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nBendirei o Senhor em todos os tempos! Seus louvores estarão sempre nos meus lábios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Minha alma será glorificada pelo Senhor. Ouçam isto e alegrem-se aqueles que possuem a mansidão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 87:2 O\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, que sois o meu Deus e o meu Salvador, tenho clamado dia e noite diante de Vós. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 10:23-37\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Beáti óculi, qui vident quæ vos videtis. Dico enim vobis, quod multi prophétæ et reges voluérunt vidére quæ vos videtis, et non vidérunt: et audire quæ audítis, et non audiérunt. Et ecce, quidam legisperítus surréxit, tentans illum, et dicens: Magister, quid faciéndo vitam ætérnam possidébo? At ille dixit ad eum: In lege quid scriptum est? quómodo legis? Ille respóndens, dixit: Díliges Dóminum, Deum tuum, ex toto corde tuo, et ex tota ánima tua, et ex ómnibus víribus tuis; et ex omni mente tua: et próximum tuum sicut teípsum. Dixítque illi: Recte respondísti: hoc fac, et vives. Ille autem volens justificáre seípsum, dixit ad Jesum: Et quis est meus próximus? Suscípiens autem Jesus, dixit: Homo quidam descendébat ab Jerúsalem in Jéricho, et íncidit in latrónes, qui étiam despoliavérunt eum: et plagis impósitis abiérunt, semivívo relícto. Accidit autem, ut sacerdos quidam descénderet eádem via: et viso illo præterívit. Simíliter et levíta, cum esset secus locum et vidéret eum, pertránsiit. Samaritánus autem quidam iter fáciens, venit secus eum: et videns eum, misericórdia motus est. Et apprópians, alligávit vulnera ejus, infúndens óleum et vinum: et impónens illum in juméntum suum, duxit in stábulum, et curam ejus egit. Et áltera die prótulit duos denários et dedit stabulário, et ait: Curam illíus habe: et quodcúmque supererogáveris, ego cum redíero, reddam tibi. Quis horum trium vidétur tibi próximus fuísse illi, qui íncidit in latrónes? At ille dixit: Qui fecit misericórdiam in illum. Et ait illi Jesus: Vade, et tu fac simíliter.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 10:23-37\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Ditosos os olhos que vêem o que vedes, pois vos digo que muitos profetas e reis quiseram ver o que vedes, e não viram, e desejaram ouvir o que ouvis, e não ouviram». Então um doutor da Lei, ouvindo isto, levantou-se, e, para tentar Jesus, disse-lhe: «Mestre, que hei-de fazer para possuir a vida eterna?». Jesus respondeu-lhe: «Que é que está escrito na Lei? De que modo lês tu?». Respondeu o doutor: «Amareis ao Senhor, vosso Deus, com todo o coração, com toda a alma, com todas as forças e com todo o entendimento; e amar reis ao vosso próximo como a vós mesmos». Jesus disse-lhe: «Respondeste com rectidão. Fale assim, e viverás». Mas o doutor, querendo justificar a sua pergunta, de novo interrogou Jesus: «E quem é o meu próximo?». Então Jesus, tomando a palavra, acrescentou: «Caminhando um homem de Jerusalém para Jericó, caiu em poder dos ladrões, que o despojaram e feriram; depois abandonaram-no semimorto. Passou por aquele caminho um Sacerdote, que viu o ferido e continuou a sua jornada. Passando, também, por ali um Levita, viu igualmente o ferido, aproximou-se um pouco e seguiu a sua viagem. Por fim, viajando por ali um Samaritano, passou perto do ferido, viu-o e encheu-se de compaixão. Logo, aproximou-se dele, deitou óleo e vinho nas feridas, cingiu-as, montou-o no seu próprio jumento, conduziu-o a uma hospedaria e cuidou dele. No outro dia, tirou dois dinheiros da sua bolsa, deu-os ao hospedeiro e disse-lhe: «Cuida deste homem; e tudo o mais que gastares te pagarei eu, quando aqui voltar». «Ora perguntou Jesus ao doutor qual destes três te parece ser o próximo do homem que caiu em poder dos ladrões?». O doutor respondeu: «Aquele que teve misericórdia dele». E Jesus terminou: «Pois tu vai e procede semelhantemente».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Exod 32:11 32:13; 32:14\u003c/I>\u003c/FONT>\u003cbr/>\nPrecátus est Moyses in conspéctu Dómini, Dei sui, et dixit: Quare, Dómine, irásceris in pópulo tuo? Parce iræ ánimæ tuæ: meménto Abraham, Isaac et Jacob, quibus jurásti dare terram fluéntem lac et mel. Et placátus factus est Dóminus de malignitáte, quam dixit fácere pópulo suo.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ex 32:11, 13-14.\u003c/I>\u003c/FONT>\u003cbr/>\nMoisés orou diante do Senhor, seu Deus, e disse: «Senhor, porque estais irritado contra o vosso povo? Aplacai a vossa ira! Lembrai-Vos de Abraão, de Isaque e de Jacob, a quem jurastes dar a posse da terra, onde. Correm leite e mel». Então o Senhor aplacou-se afastou os males com que ameaçara o povo.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias, quǽsumus, Dómine, propítius inténde, quas sacris altáribus exhibémus: ut, nobis indulgéntiam largiéndo, tuo nómini dent honórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Joachim Confessoris, Patris B. M. V.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, clementíssime Deus, sacrifícium in honórem sancti Patriarchæ Jóachim, patris Maríæ Vírginis, majestáti tuæ oblátum: ut, ipso cum cónjuge sua et beatíssima prole intercedénte, perféctam cónsequi mereámur remissiónem peccatórum et glóriam sempitérnam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos olhar propício, Senhor, para as hóstias que depomos sobre os vossos sacrossantos altares, a fim de que, obtendo-nos o perdão, sirvam de homenagem ao vosso santo nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Joaquim, Pai da Nossa Senhora\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó clementíssimo Deus, o sacrifício que oferecemos à vossa majestade em honra do santo Patriarca Joaquim, Pai da Virgem Maria, a fim de que, pela sua intercessão, unida à de sua esposa e à de sua B. Filha, mereçamos alcançar a plena remissão dos nossos pecados e a glória eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 103:13; 103:14-15\u003c/I>\u003c/FONT>\u003cbr/>\nDe fructu óperum tuórum, Dómine, satiábitur terra: ut edúcas panem de terra, et vinum lætíficet cor hóminis: ut exhílaret fáciem in óleo, et panis cor hóminis confírmet.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 103:13-15\u003c/I>\u003c/FONT>\u003cbr/>\nA terra ficará saciada com o fruto das vossas obras, Senhor! Fareis brotar da terra o pão, assim como o vinho, que alegra o coração do homem. Dar-lhe-eis azeite, que faz resplandecer o rosto do homem, e pão, que fortifica o seu coração.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nVivíficet nos, quǽsumus, Dómine, hujus participátio sancta mystérii: et páriter nobis expiatiónem tríbuat et múnimen.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Joachim Confessoris, Patris B. M. V.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uǽsumus, omnípotens Deus: ut per hæc sacraménta, quæ súmpsimus, intercedéntibus méritis et précibus beáti Jóachim patris Genetrícis dilécti Fílii tui, Dómini nostri Jesu Christi, tuæ grátiæ in præsénti et ætérnæ glóriæ in futúro partícipes esse mereámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nFazei, Senhor, Vos suplicamos, que a comparticipação deste sacrossanto mystério nos sirva igualmente de expiação e de protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Joaquim, Pai da Nossa Senhora\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>azei, ó Deus omnipotente, Vos suplicamos, que pelas preces e méritos do B. Joaquim, Pai da Mãe do vosso amado Filho, Nosso Senhor Jesus Cristo, estes sacramentos, que recebemos, nos tornem comparticipantes da vossa graça na vida presente e da vossa eterna glória na vida futura.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-17":{"date":"2026-08-17","title":"São Jacinto, confessor","forms":[{"number":1,"title":"S. Hyacinthi Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-17.txt","rule":"Gloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui nos beáti Hyacínthi Confessóris tui ánnua solemnitáte lætíficas: concéde propítius; ut cujus natalítia cólimus, étiam actiónes imitémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que nos alegrais com a solenidade anual do B. Jacinto, vosso Confessor, visto que celebramos o seu nascimento, concedei-nos propício que imitemos também as suas acções.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPelos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-18":{"date":"2026-08-18","title":"Féria da 12ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Tertia infra Hebdomadam XII post Octavam Pentecostes III. Augusti\tFeria","winner":"Tempora/Pent12-2.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 69:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, in adjutórium meum inténde: Dómine, ad adjuvándum me festína: confundántur et revereántur inimíci mei, qui quærunt ánimam meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 69:4\u003c/I>\u003c/FONT>\u003cbr/>\nAvertántur retrórsum et erubéscant: qui cógitant mihi mala.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, in adjutórium meum inténde: Dómine, ad adjuvándum me festína: confundántur et revereántur inimíci mei, qui quærunt ánimam meam.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 69:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, vinde em meu auxílio. Apressai-Vos, Senhor, em socorrer-me! Que fiquem confundidos e envergonhados os meus inimigos, que procuram tirar-me a vida.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 69:4\u003c/I>\u003c/FONT>\u003cbr/>\nFujam de mim, cheios de vergonha aqueles que querem a minha perda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, vinde em meu auxílio. Apressai-Vos, Senhor, em socorrer-me! Que fiquem confundidos e envergonhados os meus inimigos, que procuram tirar-me a vida.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens et miséricors Deus, de cujus múnere venit, ut tibi a fidélibus tuis digne et laudabíliter serviátur: tríbue, quǽsumus, nobis; ut ad promissiónes tuas sine offensióne currámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Agapiti Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>ætétur Ecclésia tua, Deus, beáti Agapíti Mártyris tui confísa suffrágiis: atque, ejus précibus gloriósis, et devóta permáneat et secúra consístat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e misericordioso, a quem os fiéis são devedores da felicidade de Vos prestarem culto agradável e digno, concedei-nos a graça, Vos suplicamos, de procurarmos sempre sem qualquer obstáculo os bens que nos prometestes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Agapito, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue a vossa Igreja, ó Deus, rejubile com a confiança que lhe dão os sufrágios do B. Agapito, vosso Mártir, e que pelas suas gloriosas preces persevere na piedade e se conserve na paz.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 3:4-9\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Fidúciam talem habémus per Christum ad Deum: non quod sufficiéntes simus cogitáre áliquid a nobis, quasi ex nobis: sed sufficiéntia nostra ex Deo est: qui et idóneos nos fecit minístros novi testaménti: non líttera, sed spíritu: líttera enim occídit, spíritus autem vivíficat. Quod si ministrátio mortis, lítteris deformáta in lapídibus, fuit in glória; ita ut non possent inténdere fili Israël in fáciem Moysi, propter glóriam vultus ejus, quæ evacuátur: quómodo non magis ministrátio Spíritus erit in glória? Nam si ministrátio damnatiónis glória est multo magis abúndat ministérium justítiæ in glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor. 3:4-9\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Devemos ter toda a confiança em Deus por Cristo, pois não somos capazes nem dum pensamento que tenha origem em nós, mas tudo nos vem de Deus. Com efeito, foi Ele quem nos tornou aptos para sermos ministros da Nova Aliança, não pela letra, mas pelo Espírito; pois a letra mata, mas o Espírito vivifica. Ora, se o ministério da morte, gravado em letras sobre as pedras, foi acompanhado de tal glória que os filhos de Israel não podiam fitar o rosto de Moisés, por causa do brilho que irradiava dele \u003cFONT SIZE='1' COLOR=\"red\">o qual, contudo, era passageiro\u003c/FONT>, como não será mais glorioso o ministério do Espírito? Se o ministério da condenação foi glorioso, incomparavelmente mais glorioso será o ministério que confere a justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 33:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícam Dóminum in omni témpore: semper laus ejus in ore meo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Dómino laudábitur ánima mea: áudiant mansuéti, et læténtur. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 87:2\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, Deus salútis meæ, in die clamávi et nocte coram te. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 33:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nBendirei o Senhor em todos os tempos! Seus louvores estarão sempre nos meus lábios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Minha alma será glorificada pelo Senhor. Ouçam isto e alegrem-se aqueles que possuem a mansidão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 87:2 O\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, que sois o meu Deus e o meu Salvador, tenho clamado dia e noite diante de Vós. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 10:23-37\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Beáti óculi, qui vident quæ vos videtis. Dico enim vobis, quod multi prophétæ et reges voluérunt vidére quæ vos videtis, et non vidérunt: et audire quæ audítis, et non audiérunt. Et ecce, quidam legisperítus surréxit, tentans illum, et dicens: Magister, quid faciéndo vitam ætérnam possidébo? At ille dixit ad eum: In lege quid scriptum est? quómodo legis? Ille respóndens, dixit: Díliges Dóminum, Deum tuum, ex toto corde tuo, et ex tota ánima tua, et ex ómnibus víribus tuis; et ex omni mente tua: et próximum tuum sicut teípsum. Dixítque illi: Recte respondísti: hoc fac, et vives. Ille autem volens justificáre seípsum, dixit ad Jesum: Et quis est meus próximus? Suscípiens autem Jesus, dixit: Homo quidam descendébat ab Jerúsalem in Jéricho, et íncidit in latrónes, qui étiam despoliavérunt eum: et plagis impósitis abiérunt, semivívo relícto. Accidit autem, ut sacerdos quidam descénderet eádem via: et viso illo præterívit. Simíliter et levíta, cum esset secus locum et vidéret eum, pertránsiit. Samaritánus autem quidam iter fáciens, venit secus eum: et videns eum, misericórdia motus est. Et apprópians, alligávit vulnera ejus, infúndens óleum et vinum: et impónens illum in juméntum suum, duxit in stábulum, et curam ejus egit. Et áltera die prótulit duos denários et dedit stabulário, et ait: Curam illíus habe: et quodcúmque supererogáveris, ego cum redíero, reddam tibi. Quis horum trium vidétur tibi próximus fuísse illi, qui íncidit in latrónes? At ille dixit: Qui fecit misericórdiam in illum. Et ait illi Jesus: Vade, et tu fac simíliter.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 10:23-37\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Ditosos os olhos que vêem o que vedes, pois vos digo que muitos profetas e reis quiseram ver o que vedes, e não viram, e desejaram ouvir o que ouvis, e não ouviram». Então um doutor da Lei, ouvindo isto, levantou-se, e, para tentar Jesus, disse-lhe: «Mestre, que hei-de fazer para possuir a vida eterna?». Jesus respondeu-lhe: «Que é que está escrito na Lei? De que modo lês tu?». Respondeu o doutor: «Amareis ao Senhor, vosso Deus, com todo o coração, com toda a alma, com todas as forças e com todo o entendimento; e amar reis ao vosso próximo como a vós mesmos». Jesus disse-lhe: «Respondeste com rectidão. Fale assim, e viverás». Mas o doutor, querendo justificar a sua pergunta, de novo interrogou Jesus: «E quem é o meu próximo?». Então Jesus, tomando a palavra, acrescentou: «Caminhando um homem de Jerusalém para Jericó, caiu em poder dos ladrões, que o despojaram e feriram; depois abandonaram-no semimorto. Passou por aquele caminho um Sacerdote, que viu o ferido e continuou a sua jornada. Passando, também, por ali um Levita, viu igualmente o ferido, aproximou-se um pouco e seguiu a sua viagem. Por fim, viajando por ali um Samaritano, passou perto do ferido, viu-o e encheu-se de compaixão. Logo, aproximou-se dele, deitou óleo e vinho nas feridas, cingiu-as, montou-o no seu próprio jumento, conduziu-o a uma hospedaria e cuidou dele. No outro dia, tirou dois dinheiros da sua bolsa, deu-os ao hospedeiro e disse-lhe: «Cuida deste homem; e tudo o mais que gastares te pagarei eu, quando aqui voltar». «Ora perguntou Jesus ao doutor qual destes três te parece ser o próximo do homem que caiu em poder dos ladrões?». O doutor respondeu: «Aquele que teve misericórdia dele». E Jesus terminou: «Pois tu vai e procede semelhantemente».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Exod 32:11 32:13; 32:14\u003c/I>\u003c/FONT>\u003cbr/>\nPrecátus est Moyses in conspéctu Dómini, Dei sui, et dixit: Quare, Dómine, irásceris in pópulo tuo? Parce iræ ánimæ tuæ: meménto Abraham, Isaac et Jacob, quibus jurásti dare terram fluéntem lac et mel. Et placátus factus est Dóminus de malignitáte, quam dixit fácere pópulo suo.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ex 32:11, 13-14.\u003c/I>\u003c/FONT>\u003cbr/>\nMoisés orou diante do Senhor, seu Deus, e disse: «Senhor, porque estais irritado contra o vosso povo? Aplacai a vossa ira! Lembrai-Vos de Abraão, de Isaque e de Jacob, a quem jurastes dar a posse da terra, onde. Correm leite e mel». Então o Senhor aplacou-se afastou os males com que ameaçara o povo.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias, quǽsumus, Dómine, propítius inténde, quas sacris altáribus exhibémus: ut, nobis indulgéntiam largiéndo, tuo nómini dent honórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Agapiti Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, Dómine, múnera, quæ in beátæ N. Vírginis et Mártyris tuæ sollemnitáte deférimus: cujus nos confídimus patrocínio liberári.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos olhar propício, Senhor, para as hóstias que depomos sobre os vossos sacrossantos altares, a fim de que, obtendo-nos o perdão, sirvam de homenagem ao vosso santo nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Agapito, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, Senhor, as ofertas que Vos apresentamos na festa daquele por cuja protecção esperamos ser livres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 103:13; 103:14-15\u003c/I>\u003c/FONT>\u003cbr/>\nDe fructu óperum tuórum, Dómine, satiábitur terra: ut edúcas panem de terra, et vinum lætíficet cor hóminis: ut exhílaret fáciem in óleo, et panis cor hóminis confírmet.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 103:13-15\u003c/I>\u003c/FONT>\u003cbr/>\nA terra ficará saciada com o fruto das vossas obras, Senhor! Fareis brotar da terra o pão, assim como o vinho, que alegra o coração do homem. Dar-lhe-eis azeite, que faz resplandecer o rosto do homem, e pão, que fortifica o seu coração.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nVivíficet nos, quǽsumus, Dómine, hujus participátio sancta mystérii: et páriter nobis expiatiónem tríbuat et múnimen.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Agapiti Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>atiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nFazei, Senhor, Vos suplicamos, que a comparticipação deste sacrossanto mystério nos sirva igualmente de expiação e de protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Agapito, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>aciastes, Senhor, a vossa família com os sacrossantos dons; e, Vos suplicamos, fortalecei-a sempre pela intercessão daquele cuja festa celebramos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-19":{"date":"2026-08-19","title":"São João Eudes, confessor","forms":[{"number":1,"title":"S. Joannis Eudes Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-19.txt","rule":"Gloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Joánnem, Confessórem tuum, ad cultum sacrórum Córdium Jesu et Maríæ rite promovéndum, mirabíliter inflammásti, et per eum novas in Ecclésia tua famílias congregáre voluísti: præsta, quǽsumus; ut, cujus pia mérita venerámur, virtútum quoque instruámur exémplis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que, para promover o culto em honra dos Sagrados Corações de Jesus e de Maria, inflamastes com zelo admirável o B. João, vosso Confessor, e por ele Vos dignastes criar novas famílias na vossa Igreja, concedei-nos, Vos pedimos, que sejamos edificados com os exemplos das virtudes daquele cujos piedosos méritos veneramos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPelos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-20":{"date":"2026-08-20","title":"São Bernardo, abade, confessor e doutor","forms":[{"number":1,"title":"S. Bernardi Abbatis et Ecclesiæ Doctoris Duplex vide Commune Doctoris non Pontificis (Missa In medio) [Commune/C5a.txt]","winner":"Sancti/08-20.txt","rule":"vide C5a;\nGloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui pópulo tuo ætérnæ salútis beátum Bernárdum minístrum tribuísti: præsta, quǽsumus; ut, quem Doctórem vitæ habúimus in terris, intercessórem habére mereámur in cælis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que ao vosso povo destinastes o B. Bernardo para ministro da eterna salvação, concedei-nos, Vos suplicamos, que, assim como o tivemos como Doutor durante a nossa vida na terra, assim gozemos a sua intercessão no céu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 39:6-14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus cor suum tradet ad vigilándum dilúculo ad Dóminum, qui fecit illum, et in conspéctu Altíssimi deprecábitur. Apériet os suum in oratióne, et pro delíctis suis deprecábitur. Si enim Dóminus magnus volúerit, spíritu intellegéntias replébit illum: et ipse tamquam imbres mittet elóquia sapiéntiæ suæ, et in oratióne confitébitur Dómino: et ipse díriget consílium ejus et disciplínam, et in abscónditis suis consiliábitur. Ipse palam fáciet disciplínam doctrínæ suæ, et in lege testaménti Dómini gloriábitur. Collaudábunt multi sapiéntiam ejus, et usque in sǽculum non delébitur. Non recédet memória ejus, et nomen ejus requirétur a generatióne in generatiónem. Sapiéntiam ejus enarrábunt gentes, et laudem ejus enuntiábit ecclésia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 39:6-14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus cor suum tradet ad vigilándum dilúculo ad Dóminum, qui fecit illum, et in conspéctu Altíssimi deprecábitur. Apériet os suum in oratióne, et pro delíctis suis deprecábitur. Si enim Dóminus magnus volúerit, spíritu intellegéntias replébit illum: et ipse tamquam imbres mittet elóquia sapiéntiæ suæ, et in oratióne confitébitur Dómino: et ipse díriget consílium ejus et disciplínam, et in abscónditis suis consiliábitur. Ipse palam fáciet disciplínam doctrínæ suæ, et in lege testaménti Dómini gloriábitur. Collaudábunt multi sapiéntiam ejus, et usque in sǽculum non delébitur. Non recédet memória ejus, et nomen ejus requirétur a generatióne in generatiónem. Sapiéntiam ejus enarrábunt gentes, et laudem ejus enuntiábit ecclésia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:9\u003c/I>\u003c/FONT>\u003cbr/>\nAmávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo falará com sabedoria e a sua língua proclamará a justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está sempre no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:9\u003c/I>\u003c/FONT>\u003cbr/>\nAmou-o o Senhor e revestiu-o com a túnica da glória. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Sois o sal da terra. Se o sal perde a força, com que salgará? Para nada mais presta, senão para se lançar fora e ser pisado pelos homens. Sois a luz do mundo. Uma cidade situada no cimo de um monte não pode ficar escondida. Nem se acende uma luz para a meter debaixo do alqueire, mas para a colocar no candeeiro, a fim de alumiar todos os que estão em casa. Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem vosso Pai, que está nos céus. Não penseis que vim abrogar a Lei ou os Profetas: não vim abrogar, mas aperfeiçoar; porque em verdade vos digo: até que passe o céu e a terra, nem um iota, nem um til se omitirá na Lei. Quem quer, pois, que transgrida, ainda um dos mais pequenos mandamentos, ou ensine os homens a violá-los, será chamado o menor no reino dos céus. Porém, quem os cumprir e ensinar será chamado grande no reino dos céus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti Bernárdi Confessóris tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti Bernardo Confessóris tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nUt nobis, Dómine, tua sacrifícia dent salútem: beátus Bernárdus Conféssor tuus et Doctor egrégius, quǽsumus, precátor accédat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nUt nobis, Dómine, tua sacrifícia dent salútem: beátus Bernardo Conféssor tuus et Doctor egrégius, quǽsumus, precátor accédat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-21":{"date":"2026-08-21","title":"Santa Joana Francisca de Chantal, viúva","forms":[{"number":1,"title":"S. Joannæ Franciscæ Frémiot de Chantal Viduæ Duplex vide Commune Unius non Virginis nec Martyris (Missa Cognovi) [Commune/C7a.txt]","winner":"Sancti/08-21.txt","rule":"vide C7a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens et miséricors Deus, qui beátam Joánnam Francíscam, tuo amóre succénsam, admirábili spíritus fortitúdine per omnes vitæ sémitas in via perfectiónis donásti, quique per illam illustráre Ecclésiam tuam nova prole voluísti: ejus méritis et précibus concéde; ut, qui infirmitátis nostræ cónscii de tua virtúte confídimus, cœléstis grátiæ auxílio cuncta nobis adversántia vincámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDeus omnipotente e eterno, que, havendo abrasado no vosso amor a B. Joana Francisca, lhe destes um admirável espírito de fortaleza para seguir em todos os caminhos da vida «a via da perfeição», e que por ela quisestes ornar a vossa Igreja com uma nova família, permiti, pelos seus méritos e preces, que, tendo nós consciência da nossa fraqueza e pondo a nossa confiança no vosso poder, triunfemos com o auxílio da graça celestial de tudo o que nos é contrário.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 31:10-31\u003c/I>\u003c/FONT>\u003cbr/>\nMulíerem fortem quis invéniet? Procul et de últimis fínibus prétium ejus. Confídit in ea cor viri sui, et spóliis non indigébit. Reddet ei bonum, et non malum, ómnibus diébus vitæ suæ. Quæsívit lanam et linum, et operáta est consílio mánuum suárum. Facta est quasi navis institóris, de longe portans panem suum. Et de nocte surréxit, dedítque prædam domésticis suis, et cibária ancíllis suis. Considerávit agrum, et emit eum: de fructu mánuum suárum plantávit víneam. Accínxit fortitúdine lumbos suos, et roborávit bráchium suum. Gustávit, et vidit, quia bona est negotiátio ejus: non exstinguétur in nocte lucérna ejus. Manum suam misit ad fórtia, et dígiti ejus apprehendérunt fusum. Manum suam apéruit ínopi, et palmas suas exténdit ad páuperem. Non timébit dómui suæ a frigóribus nivis: omnes enim doméstici ejus vestíti sunt duplícibus. Stragulátam vestem fecit sibi: byssus et púrpura induméntum ejus. Nóbilis in portis vir ejus, quando séderit cum senatóribus terræ. Síndonem fecit et véndidit, et cíngulum trádidit Chananǽo. Fortitúdo et decor induméntum ejus, et ridébit in die novíssimo. Os suum apéruit sapiéntiæ, et lex cleméntiæ in lingua ejus. Considerávit sémitas domus suæ, et panem otiósa non comédit. Surrexérunt fílii ejus, et beatíssimam prædicavérunt: vir ejus, et laudávit eam. Multæ fíliæ congregavérunt divítias: tu supergréssa es univérsas. Fallax grátia, et vana est pulchritúdo: múlier timens Dóminum, ipsa laudábitur. Date ei de fructu mánuum suárum: et laudent eam in portis ópera ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Pr 31:10-31\u003c/I>\u003c/FONT>\u003cbr/>\nQuem encontrará uma mulher forte? Seu valor é maior do que o das pérolas que vêm dos confins do mundo. Nela confia o coração do marido, que por isso lhe não faltará proveito. Ela procurará praticar o bem, e não o mal, em todos os dias da sua vida. Ela procurará a lã e o linho, e, diligentemente, trabalhará neles com suas mãos. Ela é como um navio de mercador que traz de longe o seu pão! Levanta-se quando ainda é noite, e dá alimento à família e trabalho aos servos. Ela pensa em um campo, compra-o e planta uma vinha com o trabalho de suas mãos. Cinge com vigor os seus rins e esforça os seus braços. Examina e vê que seu negócio é bom e que sua lâmpada se não apagará durante a noite. Emprega suas mãos em trabalhos rudes e seus dedos no fuso. Estende a sua mão ao indigente e o seu braço ao pobre. Não receia na sua casa nem o frio, nem a neve, porque todos os criados têm roupa em duplo. Fabrica para si tapeçarias e faz os seus vestidos de bom linho e de púrpura. Seu marido será enobrecido, quando se sentar às Portas da cidade com os senadores da terra. Faz vestidos, que vende, e cintas, que entrega aos mercadores. Revestiu-se de coragem e de glória, e, alegre, aguarda o futuro. Fala com sabedoria e a sua língua é clemente. Vigia os caminhos de sua casa e não come o pão na ociosidade. Erguem-se seus filhos e a proclamam bem-aventurada, e seu marido a louva também: «Muitas filhas reuniram virtudes, mas tu excedeste-las». Enganadora é a graça e vã é a formosura. Só a mulher, que teme o Senhor, será louvada. Dai-lhe o produto de suas mãos, e que a louvem às portas da cidade, por causa das suas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: eis porque Deus vos abençoou para a eternidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da vossa verdade, mansidão e justiça, a vossa dextra praticará maravilhas. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai, pois, com beleza e com majestade; ide gozar a vitória e reinai. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a um tesouro escondido no campo, o qual um homem acha e esconde; e, alegre com o achado, vai, vende tudo o que tem e compra o campo. Igualmente o reino dos céus é semelhante a um negociante, que busca pedras preciosas; e, achando uma de grande preço, vai, vende tudo o que tem e compra-a. O reino dos céus é ainda semelhante a uma rede que, lançada ao mar, prende toda a casta de peixes, e, estando já cheia, os pescadores a puxam para a praia, escolhem os bons peixes para os vasos e deitam fora os maus. Assim será no fim dos séculos: virão os Anjos e separarão os maus do meio dos justos e os lançarão na fornalha do fogo, onde não haverá senão fogo e ranger de dentes. Haveis compreendido tudo isto?». «Sim», responderam eles. E Jesus disse-lhes: «Por esta razão todo o escriba douto no que diz respeito ao reino dos céus é semelhante a um pai de família, que tira dos seus tesouros cousas novas e velhas».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: por isso Deus vos abençoou para a eternidade e para todos os séculos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nIllo nos amóris igne, quǽsumus, Dómine, hæc hóstia salutáris inflámmet: quo beátæ Joannæ Francíscæ cor veheménter incéndit, et flammis adússit ætérnæ caritátis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, Vos suplicamos, permiti que esta hóstia salutar nos inflame no fogo daquele amor que abrasou com tanto ardor o coração da B. Joana Francisca e o consumiu nas chamas da eterna caridade.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nDilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nAmastes a justiça e odiastes a iniquidade: eis porque o Senhor, vosso Deus, vos ungiu com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSpíritum nobis, Dómine, tuæ caritátis infúnde: ut, quos cœléstis panis virtúte satiásti, beáta Joánna Francisca intercedénte, fácias terréna despícere, et te solum Deum pura mente sectári.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nInfundi em nós, Senhor, o espírito da vossa caridade, a fim de que pela intercessão da B. Joana Francisca aqueles que saciastes com o celestial Pão dos fortes desprezem os bens da terra e com o coração puro se unam somente a Vós, ó Deus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-22":{"date":"2026-08-22","title":"Imaculado Coração de Maria","forms":[{"number":1,"title":"Immaculati Cordis Beatæ Mariæ Virginis Duplex II classis ex Commune Beatae Mariae Virginis [Commune/C11.txt]","winner":"Sancti/08-22.txt","rule":"ex C11;\nGloria\nCredo\nPrefatio=Maria=Festivitate;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Hebr 4:16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>deámus cum fidúcia ad thronum grátiæ, ut misericórdiam consequámur, et grátiam inveniámus in auxílio opportúno.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>deámus cum fidúcia ad thronum grátiæ, ut misericórdiam consequámur, et grátiam inveniámus in auxílio opportúno.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Heb 4:16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>cerquemo-nos com confiança do trono da graça, a fim de alcançar misericórdia e encontrar graça e sermos auxiliados na ocasião necessária.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: «Consagro ao Rei as minhas obras»!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>cerquemo-nos com confiança do trono da graça, a fim de alcançar misericórdia e encontrar graça e sermos auxiliados na ocasião necessária.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui in Corde beátæ Maríæ Vírginis dignum Spíritus Sancti habitáculum præparásti: concéde propítius; ut ejúsdem immaculáti Cordis festivitátem devóta mente recoléntes, secúndum cor tuum vívere valeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Timothei, Hippolyti et Symphoriani Martyres\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>uxílium tuum nobis, Dómine, quǽsumus, placátus impende: et, intercedéntibus beátis Martýribus tuis Timótheo, Hippolýto et Symphoriáno, déxteram super nos tuæ propitiatiónis exténde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOmnipotente e sempiterno Deus, que no Coração da B. V. Maria preparastes uma digna morada do Espírito Santo, concedi-nos propício que, havendo celebrado devotamente a festa deste Imaculado Coração, vivamos sempre segundo o vosso Coração.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Timóteo, Hipólito e Sinforiano\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eixai-Vos aplacar, Senhor, e concedei-nos o vosso auxílio; e pela intercessão dos vossos B. B. Mártires Timóteo, Hipólito e Sinforiano dignai-Vos amparar-nos com vossa mão propícia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:23-31\u003c/I>\u003c/FONT>\u003cbr/>\nEgo quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:23-31\u003c/I>\u003c/FONT>\u003cbr/>\nEu produzi, como a vinha, flores de suave odor, e as minhas flores são frutos de honra e de honestidade. Eu sou a mãe do amor puro, do temor, da ciência e da esperança santa. Em mim existe toda a graça do caminho e da verdade; em mim existe toda a esperança da vida e da virtude. Vinde a mim, ó vós, que me desejais com ardor, e saciai-vos com meus frutos; pois o meu espírito é mais doce do que o mel e a minha herança excede em doçura o próprio favo de mel! Minha memória permanecerá nas gerações de todos os séculos. Aqueles que me comerem terão ainda fome; e aqueles que me beberem terão ainda sede. Aqueles que me escutam não serão confundidos; aqueles que se orientarem em mim não pecarão; e aqueles que me tornarem conhecida alcançarão a vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 12:6\u003c/I>\u003c/FONT>\u003cbr/>\nExsultábit cor meum in salutári tuo: cantábo Dómino, qui bona tríbuit mihi: et psallam nómini Dómini altíssimi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:18\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Mémores erunt nóminis tui in omni generatióne et generatiónem: proptérea pópuli confitebúntur tibi in ætérnum. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Luc 1:46; 1:47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Magníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo salutári meo. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 12:6\u003c/I>\u003c/FONT>\u003cbr/>\nExultará o meu coração com a salvação que de Vós virá; cantarei hinos ao Senhor, que me concedeu tantos benefícios; entoarei salmos em louvor do nome do altíssimo Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:18\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> De geração em geração glorificarão o vosso nome: e os povos vos louvarão eternamente. Aleluia, aleluia\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Lc 1:46; 1:47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Minha alma glorifica o Senhor e o meu espírito se alegra em Deus, meu Salvador. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 19:25-27\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Stabant juxta crucem Jesu mater ejus, et soror matris ejus María Cléophæ, et María Magdaléne. Cum vidísset ergo Jesus matrem, et discípulum stantem, quem diligébat, dicit matri suæ: Múlier, ecce fílius tuus. Deinde dicit discípulo: Ecce mater tua. Et ex illa hora accépit eam discípulus in sua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 19:25-27\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, estavam, junto à cruz de Jesus, sua Mãe e a irmã de sua Mãe, Maria, mulher de Cléofas, e Maria Madalena. Vendo Jesus sua Mãe e, perto dela, o discípulo que Ele preferia, disse a sua Mãe: «Mulher, eis o vosso filho!». Depois disse ao discípulo: «Eis a tua Mãe!». E desde aquela hora levou-a o discípulo consigo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:46; 1:49\u003c/I>\u003c/FONT>\u003cbr/>\nExsultávit spíritus meus in Deo salutári meo; quia fecit mihi magna qui potens est, et sanctum nomen ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:46; 1:49\u003c/I>\u003c/FONT>\u003cbr/>\nO meu espírito alegra-se em Deus, meu Salvador, porque Aquele que é omnipotente, e o seu nome é Santo, operou em mim maravilhas.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nMajestáti tuæ, Dómine, Agnum immaculátum offeréntes, quǽsumus: ut corda nostra ignis ille divínus accéndat, cui Cor beátæ Maríæ Vírginis ineffabíliter inflammávit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Timothei, Hippolyti et Symphoriani Martyres\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nEnquanto oferecemos à vossa Majestade, Senhor, o Cordeiro Imaculado, dignai-Vos acender nos nossos corações aquele fogo divino que abrasou de uma maneira inefável o Coração da B. V. Maria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Timóteo, Hipólito e Sinforiano\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in Festivitate beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 19:27\u003c/I>\u003c/FONT>\u003cbr/>\nDixit Jesus matri suæ: Múlier, ecce fílius tuus: deinde dixit discípulo: Ecce mater tua. Et ex illa hora accépit eam discípulus in sua.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 19:27\u003c/I>\u003c/FONT>\u003cbr/>\nDisse Jesus a sua Mãe: «Mulher, eis o vosso filho»; depois disse ao discípulo: «Eis a tua Mãe». E desde aquela hora o discípulo a levou consigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDivínis refécti munéribus te, Dómine, supplíciter exorámus: ut beátæ Maríæ Vírginis intercessióne, cujus immaculáti Cordis sollémnia venerándo égimus, a præséntibus perículis liberáti, ætérnæ vitæ gáudia consequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Timothei, Hippolyti et Symphoriani Martyres\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ivíni múneris largitáte satiáti, quǽsumus, Dómine, Deus noster: ut, intercedéntibus sanctis Martýribus tuis Timótheo, Hippolýto et Symphoriáno, in ejus semper participatióne vivámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSustentados com vossas divinas ofertas, Senhor, humildemente Vos imploramos pela intercessão da B. V. Maria, cujo puríssimo Coração acabamos solenemente de honrar, que, sendo livres dos perigos presentes, possamos gozar a alegria da vida eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Timóteo, Hipólito e Sinforiano\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>aciados abundantemente com o dom divino, ó Senhor, nosso Deus, Vos suplicamos, fazei, pela intercessão dos vossos Santos Mártires Timóteo, Hipólito e Sinforiano, que participemos sempre dele durante toda nossa vida.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-23":{"date":"2026-08-23","title":"XIII Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XIII Post Pentecosten IV. Augusti\tSemiduplex","winner":"Tempora/Pent13-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 73:20; 73:19; 73:23\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>éspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 73:1\u003c/I>\u003c/FONT>\u003cbr/>\nUt quid, Deus, reppulísti in finem: irátus est furor tuus super oves páscuæ tuæ?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>éspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 73:20; 73:19; 73:23\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-vos, Senhor, da vossa aliança connosco e não esqueçais para sempre as almas dos vossos servos. Erguei-Vos, Senhor, julgai a vossa causa: e não desprezeis as orações daqueles que a Vós recorrem. Porque, ó Deus, nos repelistes para sempre?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 73:1\u003c/I>\u003c/FONT>\u003cbr/>\nPorque, ó Deus, cresceu a vossa ira contra as ovelhas dos vossos pastos?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-vos, Senhor, da vossa aliança connosco e não esqueçais para sempre as almas dos vossos servos. Erguei-Vos, Senhor, julgai a vossa causa: e não desprezeis as orações daqueles que a Vós recorrem. Porque, ó Deus, nos repelistes para sempre?\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, da nobis fídei, spei et caritátis augméntum: et, ut mereámur asséqui quod promíttis, fac nos amáre quod prǽcipis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e sempiterno, concedei-nos o aumento da fé, da esperança e da caridade; e, a fim de merecermos alcançar o que nos prometestes, permiti que amemos o que nos preceituais.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Gálatas\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gal 3:16-22\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Abrahæ dictæ sunt promissiónes, et sémini ejus. Non dicit: Et semínibus, quasi in multis; sed quasi in uno: Et sémini tuo, qui est Christus. Hoc autem dico: testaméntum confirmátum a Deo, quæ post quadringéntos et trigínta annos facta est lex, non írritum facit ad evacuándam promissiónem. Nam si ex lege heréditas, jam non ex promissióne. Abrahæ autem per repromissiónem donávit Deus. Quid igitur lex? Propter transgressiónes pósita est, donec veníret semen, cui promíserat, ordináta per Angelos in manu mediatóris. Mediátor autem uníus non est: Deus autem unus est. Lex ergo advérsus promíssa Dei? Absit. Si enim data esset lex, quæ posset vivificáre, vere ex lege esset justítia. Sed conclúsit Scriptúra ómnia sub peccáto, ut promíssio ex fide Jesu Christi darétur credéntibus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Gálatas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gl 3:16-22\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: As promessas foram feitas a Abraão e à sua descendência. Pois a Escritura não diz «aos seus descendentes», como se se referisse a muitos, mas diz, referindo-se a um só: «e Àquele que nascerá de vós, isto é, Cristo». Portanto digo: Deus, tendo feito e confirmado uma aliança, a Lei, que foi dada somente quatrocentos e trinta anos depois, não poderá anular nem destruir a promessa. Ora, se pela Lei é que somos herdeiros da bênção, já esta não vem da promessa, ainda que tenha sido em virtude da promessa que a bênção foi dada a Abraão. Para que serve, pois, a Lei? Ela foi dada por causa das transgressões, até que viesse «a descendência», à qual havia sido feita a promessa. Ela foi promulgada pelos Anjos por meio dum mediador. Ora, um mediador o não é para um só, e Deus é um só. Logo é a Lei contrária à promessa de Deus? De nenhum modo. Se a Lei tivesse podido dar a vida verdadeira, então a justiça viria também, verdadeiramente, da Lei; mas a Escritura encerrou tudo sob o pecado, a fim de que a promessa fosse dada pela fé em Jesus Cristo àqueles que acreditassem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 73:20; 73:19; 73:22\u003c/I>\u003c/FONT>\u003cbr/>\nRéspice, Dómine, in testaméntum tuum: et ánimas páuperum tuórum ne obliviscáris in finem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Exsúrge, Dómine, et júdica causam tuam: memor esto oppróbrii servórum tuórum. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 89:1\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, refúgium factus es nobis a generatióne et progénie. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 73:20, 19, 22.\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos, Senhor, da vossa aliança connosco e não esqueçais para sempre as almas dos vossos servos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Erguei-Vos, Senhor, julgai a vossa causa e lembrai-Vos dos opróbrios que sofreram os vossos servos. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 89:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> De geração em geração, Senhor tendes sido o nosso refúgio. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 17:11-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dum iret Jesus in Jerúsalem, transíbat per médiam Samaríam et Galilǽam. Et cum ingrederétur quoddam castéllum, occurrérunt ei decem viri leprósi, qui stetérunt a longe; et levavérunt vocem dicéntes: Jesu præcéptor, miserére nostri. Quos ut vidit, dixit: Ite, osténdite vos sacerdótibus. Et factum est, dum irent, mundáti sunt. Unus autem ex illis, ut vidit quia mundátus est, regréssus est, cum magna voce magníficans Deum, et cecidit in fáciem ante pedes ejus, grátias agens: et hic erat Samaritánus. Respóndens autem Jesus, dixit: Nonne decem mundáti sunt? et novem ubi sunt? Non est invéntus, qui redíret et daret glóriam Deo, nisi hic alienígena. Et ait illi: Surge, vade; quia fides tua te salvum fecit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 17:11-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, indo Jesus para Jerusalém, atravessou a Samaria e a Galileia. Entrando, então, numa aldeia, foram ao seu encontro \u003cFONT SIZE='1' COLOR=\"red\">ficando, contudo, a certa distância\u003c/FONT> dez leprosos, que clamavam: «Jesus, Mestre, tende misericórdia de nós!». Quando Jesus os viu, disse-lhes: «Ide e mostrai-vos aos sacerdotes». Enquanto eles iam, foram curados, Então um deles, vendo-se curado, voltou para trás, glorificando Deus em voz alta; e, prostrando-se com o rosto no chão, aos pés de Jesus, deu-Lhe graças! Este era samaritano. Jesus disse: «Porventura não foram os dez curados? Onde estão, pois, os outros nove? Não houve senão este estrangeiro que viesse e rendesse glória a Deus?». E, dirigindo-se a ele, acrescentou: «Levanta-te e vai: a tua fé te salvo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 30:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nIn te sperávi, Dómine; dixi: Tu es Deus meus, in mánibus tuis témpora mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 30:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nEm Vós, Senhor, pus toda minha esperança; e disse: Vós sois o meu Deus; a minha vida está nas vossas mãos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPropitiáre, Dómine, pópulo tuo, propitiáre munéribus: ut, hac oblatióne placátus, et indulgéntiam nobis tríbuas et postuláta concedas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nOlhai propício para o vosso povo, Senhor, e aceitai benignamente as nossas ofertas, a fim de que, deixando-Vos aplacar com esta oferta, nos concedais o perdão e atendais às nossas súplicas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sap 16:20\u003c/I>\u003c/FONT>\u003cbr/>\nPanem de cœlo dedísti nobis, Dómine, habéntem omne delectaméntum et omnem sapórem suavitátis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 16:20\u003c/I>\u003c/FONT>\u003cbr/>\nDestes-nos, Senhor, um pão do céu, que contém todas as delícias e o mais suave sabor.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, cœléstibus sacraméntis: ad redemptiónis ætérnæ, quǽsumus, proficiámus augméntum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós recebido estes celestiais sacramentos, Senhor, concedei-nos a graça, Vos imploramos, de progredirmos sempre no caminho da salvação eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-24":{"date":"2026-08-24","title":"São Bartolomeu, apóstolo","forms":[{"number":1,"title":"S. Bartholomæi Apostoli Duplex II classis ex Commune Apostolorum [Commune/C1.txt]","winner":"Sancti/08-24.txt","rule":"ex C1;\nGloria\nCredo\nPrefatio=Apostolis\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:1-2.\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>onrais largamente os vossos amigos, ó Deus: e o seu poder tem-se fortalecido extraordinariamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, perscrutastes o meu íntimo e ficastes conhecendo-me: ficastes conhecendo quando me deito e quando me levanto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>onrais largamente os vossos amigos, ó Deus: e o seu poder tem-se fortalecido extraordinariamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui hujus diei venerándam sanctámque lætítiam in beáti Apóstoli tui Bartholomǽi festivitáte tribuísti: da Ecclésiæ tuæ, quǽsumus; et amáre quod crédidit, et prædicáre quod dócuit.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e sempiterno, que neste dia, em que celebramos a festa do B. Bartolomeu, Apóstolo, nos proporcionais uma santa e veneranda alegria, concedei à vossa Igreja, Vos suplicamos, o dom de amar o que ele acreditou e de pregar o que ensinou.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 12:27-31\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Vos estis corpus Christi et membra de membro. Et quosdam quidem pósuit Deus in Ecclésia primum apóstolos, secúndo prophetas, tertio doctores, deinde virtútes, exinde grátias curationum, opitulatiónes, gubernatiónes, genera linguarum, interpretatiónes sermonum. Numquid omnes apóstoli? numquid omnes prophétæ? numquid omnes doctóres? numquid omnes virtútes? numquid omnes grátiam habent curationum? numquid omnes linguis loquúntur? numquid omnes interpretántur? Æmulámini autem charísmata melióra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 12:27-31\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Sois os corpos de Cristo e os membros uns dos outros. Assim, Deus estabeleceu na sua Igreja primeiramente Apóstolos, em segundo lugar Profetas, em terceiro lugar Doutores, depois os que fazem milagres, em seguida os que têm o dom de curar, de assistir, de governar, de falar várias línguas e de interpretá-las. Porém são todos Apóstolos? São todos Profetas? São todos Doutores? Fazem todos milagres? Têm todos o dom de curar? Falam todos as línguas? Têm todos o dom de interpretá-las? Aspirai aos dons mais perfeitos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:17; 44:18\u003c/I>\u003c/FONT>\u003cbr/>\nConstítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Pro patribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Te gloriósus Apostolórum chorus laudat, Dómine. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:17; 44:18\u003c/I>\u003c/FONT>\u003cbr/>\nSerão constituídos príncipes em toda a terra e perpetuarão a glória do vosso nome, Senhor!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Para substituir os vossos pais, nascer-vos-ão filhos; por isso os povos Vos honrarão eternamente. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O coro glorioso dos Apóstolos canta os vossos louvores. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 6:12-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Exiit Jesus in montem oráre, et erat pernóctans in oratióne Dei. Et cum dies factus esset, vocavit discípulos suos, et elégit duódecim ex ipsis - quos et Apóstolos nominávit -: Simónem, quem cognominávit Petrum, et Andream fratrem ejus, Jacóbum et Joánnem, Philíppum et Bartholomæum, Matthǽum et Thomam, Jacóbum Alphæi et Simónem, qui vocátur Zelótes, et Judam Jacóbi, et Judam Iscariótem, qui fuit próditor. Et descéndens cum illis, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judæa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui vénerant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 6:12-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, retirara-se Jesus para um monte, e aí passara toda a noite em oração a Deus. Quando o dia rompeu, chamou os discípulos e escolheu doze de entre eles, aos quais chamou Apóstolos: Simão, a quem deu o cognome de Pedro, e André, seu irmão, Tiago e João, Filipe e Bartolomeu, Mateus e Tomé, Tiago, filho de Alfeu, e Simão, chamado o Zelote, Judas, irmão de Tiago, e Judas Iscariotes, que foi o traidor. E, descendo com eles, parou em um campo, onde encontrou a turba dos discípulos e uma grande multidão de povo de toda a Judeia, de Jerusalém e das paragens de Tiro e de Sidónia, que tinham vindo para O ouvirem e para que seus enfermos fossem curados. Entre eles havia alguns que estavam possessos de espíritos imundos, os quais foram curados. Toda aquela multidão procurava tocar em Jesus, pois d’Ele saía uma tal virtude que a todos sarava.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:17\u003c/I>\u003c/FONT>\u003cbr/>\nMihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:17\u003c/I>\u003c/FONT>\u003cbr/>\nEu vejo, ó Deus, que honrais largamente os vossos amigos; e por isso o seu poder se tem fortalecido extraordinariamente.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBeáti Apóstoli tui Bartholomǽi sollémnia recenséntes, quǽsumus, Dómine: ut ejus auxílio tua benefícia capiámus, pro quo tibi laudis hóstias immolámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nCelebrando a festa do B. Bartolomeu, vosso Apóstolo, fazei, Senhor, Vos suplicamos, que alcancemos os vossos benefícios pelo socorro daquele em cuja honra imolamos esta hóstia de louvor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Apostolis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Apóstolos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua protecção, a fim de que seja sempre governado pelos mesmos Directores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:28\u003c/I>\u003c/FONT>\u003cbr/>\nVos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:28\u003c/I>\u003c/FONT>\u003cbr/>\nVós, que me seguistes, vos assentareis sobre tronos e julgareis as doze tribos de Israel.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptum, Dómine, pignus redemptiónis ætérnæ: sit nobis, quǽsumus; interveniénte beáto Bartholomǽo Apóstolo tuo, vitæ præséntis auxílium páriter et futúræ.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, que o penhor da redenção eterna, que recebemos, seja para nós, por intercessão do B. Bartolomeu, Apóstolo, auxílio na vida presente e na futura.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-25":{"date":"2026-08-25","title":"São Luís, rei, rei e confessor","forms":[{"number":1,"title":"S. Ludovici Regis Franciæ Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-25.txt","rule":"Evangelium non appropriatum\nvide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Ludovícum Confessórem tuum de terréno regno ad cœléstis regni glóriam transtulísti: ejus, quǽsumus, méritis et intercessióne; Regis regum Jesu Christi, Fílii tui, fácias nos esse consórtes:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que trasladastes o B. Luís, vosso Confessor, do reino terrestre para a glória do reino celestial, humildemente Vos suplicamos, pelos seus méritos e intercessão, que um dia nos façais participar da glória do Rei dos reis, Jesus Cristo, vosso Filho.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sap 10:10-14\u003c/I>\u003c/FONT>\u003cbr/>\nJustum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 10: 10-14\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor conduziu o justo por caminhos direitos; mostrou-lhe o reino de Deus; transmitiu-lhe a ciência das cousas santas; enriqueceu-o nos seus trabalhos; e fez frutificar esses seus labores. O Senhor auxiliou-o contra os que queriam enganá-lo com suas fraudes e fê-lo adquirir riquezas. Protegeu-o contra os seus inimigos; defendeu-o de seus sedutores; e alcançou a vitória em um rude combate em seu favor, para lhe ensinar que a sabedoria é a mais poderosa de todas as cousas. O Senhor não abandonou o justo quando este foi vendido, mas até o preservou das mãos dos pecadores; desceu com ele á prisão; e o não abandonou nas cadeias, enquanto lhe não entregou o ceptro do império e o poder sobre os seus opressores. O Senhor, nosso Deus, provou que eram mentirosos aqueles que o desacreditaram e tornou-o ilustre para sempre.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 19:12-26\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo quidam nóbilis ábiit in regionem longínquam accípere sibi regnum, et revérti. Vocátis autem decem servis suis, dedit eis decem mnas, et ait ad illos: Negotiámini, dum vénio. Cives autem ejus óderant eum: et misérunt legatiónem post illum, dicéntes: Nólumus hunc regnáre super nos. Et factum est, ut redíret accépto regno: et jussit vocári servos, quibus dedit pecúniam, ut sciret, quantum quisque negotiátus esset. Venit autem primus, dicens: Dómine, mna tua decem mnas acquisívit. Et ait illi: Euge, bone serve, quia in módico fuísti fidélis, eris potestátem habens super decem civitátes. Et alter venit, dicens: Dómine, mna tua fecit quinque mnas. Et huic ait: Et tu esto super quinque civitátes. Et alter venit, dicens: Dómine, ecce mna tua, quam hábui repósitam in sudário: tímui enim te, quia homo austérus es: tollis, quod non posuísti, et metis, quod non seminásti. Dicit ei: De ore tuo te júdico, serve nequam. Sciébas, quod ego homo austérus sum, tollens, quod non pósui, et metens, quod non seminávi: et quare non dedísti pecúniam meam ad mensam, ut ego véniens cum usúris útique exegíssem illam? Et astántibus dixit: Auferte ab illo mnam et date illi, qui decem mnas habet. Et dixérunt ei: Dómine, habet decem mnas. Dico autem vobis: Quia omni habénti dábitur, et abundábit: ab eo autem, qui non habet, et, quod habet, auferétur ab eo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 19:12-26\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus disse aos seus discípulos esta parábola: «Certo homem de linhagem nobre partiu para um país longínquo, a fim de conseguir a posse desse reino e voltar depois. Chamou, pois, dez dos seus servos, deu-lhes dez moedas e disse-lhes: «Negociai com elas até eu voltar». Porém os seus concidadãos, que o odiavam, enviaram uma embaixada após ele, dizendo: «Não queremos que este homem seja nosso rei”. Ora aconteceu que, quando regressou, revestido da realeza, mandou chamar os servos, a quem havia dado o dinheiro, para saber como haviam negociado. Veio o primeiro e disse-lhe: «Vossa moeda, senhor, rendeu dez moedas». Respondeu-lhe o senhor: «Está bem, servo bom; visto que foste fiel em pouca coisa, recebe o governo de dez cidades». Veio o segundo e disse-lhe: «Vossa moeda, senhor, rendeu cinco moedas». Respondeu-lhe o senhor: «Tu governarás cinco cidades». Veio também o terceiro e disse: «Eis a vossa moeda, senhor, que eu guardei em um pano; pois tive medo de vós, que sois homem austero: tirais o que não depositais e recolheis o que não semeais». Respondeu-lhe o senhor: «Eu te julgarei com tuas próprias palavras, ó servo mau. Tu sabes que sou homem severo, tirando o que não depositei e colhendo o que não semeei; porque, então, não depositaste o meu dinheiro em um banco, para que, quando regressasse, o recolhesse com os juros?». Depois, continuou o senhor, dirigindo-se aos presentes: «Tirai-lhe a moeda e dai-a ao que tem dez». E eles disseram-lhe: «Ele já tem dez moedas». «Eu vos digo, retorquiu o Senhor, dar-se-á àquele que tem, e ficará na abundância; mas àquele que nada tem tirar-se-lhe-á até o que tiver».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPræsta, quǽsumus, omnípotens Deus: ut, sicut beátus Ludovícus Conféssor tuus, spretis mundi oblectaméntis, soli Regi Christo placére stúduit; ita ejus orátio nos tibi reddat accéptos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Deus omnipotente, Vos suplicamos, fazei que, assim como o B. Luís, vosso Confessor, desprezando as delícias do mundo só procurou agradar a Cristo-Rei, assim também a sua oração nos torne agradáveis a Vós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Confessórem tuum Ludovícum mirificásti in terris, et gloriósum in cœlis fecísti: eúndem, quǽsumus, Ecclésiæ tuæ constítue defensórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que engrandecestes na terra e glorificastes no céu o B. Luís, vosso Confessor, constituí-o, Vo-lo pedimos, defensor da vossa Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-26":{"date":"2026-08-26","title":"Féria da 13ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria Quarta infra Hebdomadam XIII post Octavam Pentecostes IV. Augusti\tFeria","winner":"Tempora/Pent13-3.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 73:20; 73:19; 73:23\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>éspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 73:1\u003c/I>\u003c/FONT>\u003cbr/>\nUt quid, Deus, reppulísti in finem: irátus est furor tuus super oves páscuæ tuæ?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>éspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 73:20; 73:19; 73:23\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-vos, Senhor, da vossa aliança connosco e não esqueçais para sempre as almas dos vossos servos. Erguei-Vos, Senhor, julgai a vossa causa: e não desprezeis as orações daqueles que a Vós recorrem. Porque, ó Deus, nos repelistes para sempre?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 73:1\u003c/I>\u003c/FONT>\u003cbr/>\nPorque, ó Deus, cresceu a vossa ira contra as ovelhas dos vossos pastos?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-vos, Senhor, da vossa aliança connosco e não esqueçais para sempre as almas dos vossos servos. Erguei-Vos, Senhor, julgai a vossa causa: e não desprezeis as orações daqueles que a Vós recorrem. Porque, ó Deus, nos repelistes para sempre?\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, da nobis fídei, spei et caritátis augméntum: et, ut mereámur asséqui quod promíttis, fac nos amáre quod prǽcipis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Zephyrini Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>regem tuum, Pastor ætérne, placátus inténde: et, per beátum Zephyrínum Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e sempiterno, concedei-nos o aumento da fé, da esperança e da caridade; e, a fim de merecermos alcançar o que nos prometestes, permiti que amemos o que nos preceituais.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Zephirini Papae et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Pastor eterno, atendei propício ao vosso rebanho; e guardai-o com vossa perpétua protecção por intercessão do bem-aventurado Zephyrínum Vosso Mártir e Sumo Pontífice, o qual escolhestes como pastor de toda a Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Gálatas\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gal 3:16-22\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Abrahæ dictæ sunt promissiónes, et sémini ejus. Non dicit: Et semínibus, quasi in multis; sed quasi in uno: Et sémini tuo, qui est Christus. Hoc autem dico: testaméntum confirmátum a Deo, quæ post quadringéntos et trigínta annos facta est lex, non írritum facit ad evacuándam promissiónem. Nam si ex lege heréditas, jam non ex promissióne. Abrahæ autem per repromissiónem donávit Deus. Quid igitur lex? Propter transgressiónes pósita est, donec veníret semen, cui promíserat, ordináta per Angelos in manu mediatóris. Mediátor autem uníus non est: Deus autem unus est. Lex ergo advérsus promíssa Dei? Absit. Si enim data esset lex, quæ posset vivificáre, vere ex lege esset justítia. Sed conclúsit Scriptúra ómnia sub peccáto, ut promíssio ex fide Jesu Christi darétur credéntibus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Gálatas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gl 3:16-22\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: As promessas foram feitas a Abraão e à sua descendência. Pois a Escritura não diz «aos seus descendentes», como se se referisse a muitos, mas diz, referindo-se a um só: «e Àquele que nascerá de vós, isto é, Cristo». Portanto digo: Deus, tendo feito e confirmado uma aliança, a Lei, que foi dada somente quatrocentos e trinta anos depois, não poderá anular nem destruir a promessa. Ora, se pela Lei é que somos herdeiros da bênção, já esta não vem da promessa, ainda que tenha sido em virtude da promessa que a bênção foi dada a Abraão. Para que serve, pois, a Lei? Ela foi dada por causa das transgressões, até que viesse «a descendência», à qual havia sido feita a promessa. Ela foi promulgada pelos Anjos por meio dum mediador. Ora, um mediador o não é para um só, e Deus é um só. Logo é a Lei contrária à promessa de Deus? De nenhum modo. Se a Lei tivesse podido dar a vida verdadeira, então a justiça viria também, verdadeiramente, da Lei; mas a Escritura encerrou tudo sob o pecado, a fim de que a promessa fosse dada pela fé em Jesus Cristo àqueles que acreditassem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 73:20; 73:19; 73:22\u003c/I>\u003c/FONT>\u003cbr/>\nRéspice, Dómine, in testaméntum tuum: et ánimas páuperum tuórum ne obliviscáris in finem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Exsúrge, Dómine, et júdica causam tuam: memor esto oppróbrii servórum tuórum. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 89:1\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, refúgium factus es nobis a generatióne et progénie. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 73:20, 19, 22.\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos, Senhor, da vossa aliança connosco e não esqueçais para sempre as almas dos vossos servos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Erguei-Vos, Senhor, julgai a vossa causa e lembrai-Vos dos opróbrios que sofreram os vossos servos. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 89:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> De geração em geração, Senhor tendes sido o nosso refúgio. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 17:11-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dum iret Jesus in Jerúsalem, transíbat per médiam Samaríam et Galilǽam. Et cum ingrederétur quoddam castéllum, occurrérunt ei decem viri leprósi, qui stetérunt a longe; et levavérunt vocem dicéntes: Jesu præcéptor, miserére nostri. Quos ut vidit, dixit: Ite, osténdite vos sacerdótibus. Et factum est, dum irent, mundáti sunt. Unus autem ex illis, ut vidit quia mundátus est, regréssus est, cum magna voce magníficans Deum, et cecidit in fáciem ante pedes ejus, grátias agens: et hic erat Samaritánus. Respóndens autem Jesus, dixit: Nonne decem mundáti sunt? et novem ubi sunt? Non est invéntus, qui redíret et daret glóriam Deo, nisi hic alienígena. Et ait illi: Surge, vade; quia fides tua te salvum fecit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 17:11-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, indo Jesus para Jerusalém, atravessou a Samaria e a Galileia. Entrando, então, numa aldeia, foram ao seu encontro \u003cFONT SIZE='1' COLOR=\"red\">ficando, contudo, a certa distância\u003c/FONT> dez leprosos, que clamavam: «Jesus, Mestre, tende misericórdia de nós!». Quando Jesus os viu, disse-lhes: «Ide e mostrai-vos aos sacerdotes». Enquanto eles iam, foram curados, Então um deles, vendo-se curado, voltou para trás, glorificando Deus em voz alta; e, prostrando-se com o rosto no chão, aos pés de Jesus, deu-Lhe graças! Este era samaritano. Jesus disse: «Porventura não foram os dez curados? Onde estão, pois, os outros nove? Não houve senão este estrangeiro que viesse e rendesse glória a Deus?». E, dirigindo-se a ele, acrescentou: «Levanta-te e vai: a tua fé te salvo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 30:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nIn te sperávi, Dómine; dixi: Tu es Deus meus, in mánibus tuis témpora mea.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 30:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nEm Vós, Senhor, pus toda minha esperança; e disse: Vós sois o meu Deus; a minha vida está nas vossas mãos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPropitiáre, Dómine, pópulo tuo, propitiáre munéribus: ut, hac oblatióne placátus, et indulgéntiam nobis tríbuas et postuláta concedas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Zephyrini Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>blátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nOlhai propício para o vosso povo, Senhor, e aceitai benignamente as nossas ofertas, a fim de que, deixando-Vos aplacar com esta oferta, nos concedais o perdão e atendais às nossas súplicas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Zephirini Papae et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>om as ofertas destes dons, Vos suplicamos, Senhor, iluminai benignamente a vossa Igreja, a fim de que não só o vosso rebanho triunfe em toda a parte, mas também pelo poder do vosso nome os pastores sejam bem acolhidos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sap 16:20\u003c/I>\u003c/FONT>\u003cbr/>\nPanem de cœlo dedísti nobis, Dómine, habéntem omne delectaméntum et omnem sapórem suavitátis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 16:20\u003c/I>\u003c/FONT>\u003cbr/>\nDestes-nos, Senhor, um pão do céu, que contém todas as delícias e o mais suave sabor.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, cœléstibus sacraméntis: ad redemptiónis ætérnæ, quǽsumus, proficiámus augméntum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Zephyrini Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós recebido estes celestiais sacramentos, Senhor, concedei-nos a graça, Vos imploramos, de progredirmos sempre no caminho da salvação eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Zephirini Papae et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos suplicamos, governai com mansidão a vossa Igreja, agora que foi alimentada com a sagrada refeição, a fim de que, dirigida com firme suavidade, alcance o incremento da sua liberdade e persista na integridade da sua doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-27":{"date":"2026-08-27","title":"São José de Calasanz, confessor","forms":[{"number":1,"title":"S. Josephi Calasanctii Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-27.txt","rule":"vide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 33:12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eníte, fílii, audíte me: timórem Dómini docébo vos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 33:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedícam Dóminum in omni témpore: semper laus ejus in ore meo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eníte, fílii, audíte me: timórem Dómini docébo vos.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 33:12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>inde, meus filhos; escutai-me e vos ensinarei a temer o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 33:2\u003c/I>\u003c/FONT>\u003cbr/>\nBendirei o Senhor em todas as ocasiões: o seu louvor estará sempre na minha boca.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>inde, meus filhos; escutai-me e vos ensinarei a temer o Senhor.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui per sanctum Joséphum Confessórem tuum, ad erudiéndam spíritu intellegéntiæ ac pietátis juventútem, novum Ecclésiæ tuæ subsídium providére dignátus es: præsta, quǽsumus; nos, ejus exémplo et intercessióne, ita fácere et docére, ut præmia consequámur ætérna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que por S. José, vosso Confessor, Vos dignastes proporcionar à vossa Igreja novo auxílio para a formação da juventude na ciência e na piedade, concedei-nos, vos rogamos, que pelo seu exemplo e intercessão possamos proceder e ensinar de tal modo que consigamos alcançar os prémios eternos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sap 10:10-14\u003c/I>\u003c/FONT>\u003cbr/>\nJustum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 10: 10-14\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor conduziu o justo por caminhos direitos; mostrou-lhe o reino de Deus; transmitiu-lhe a ciência das cousas santas; enriqueceu-o nos seus trabalhos; e fez frutificar esses seus labores. O Senhor auxiliou-o contra os que queriam enganá-lo com suas fraudes e fê-lo adquirir riquezas. Protegeu-o contra os seus inimigos; defendeu-o de seus sedutores; e alcançou a vitória em um rude combate em seu favor, para lhe ensinar que a sabedoria é a mais poderosa de todas as cousas. O Senhor não abandonou o justo quando este foi vendido, mas até o preservou das mãos dos pecadores; desceu com ele á prisão; e o não abandonou nas cadeias, enquanto lhe não entregou o ceptro do império e o poder sobre os seus opressores. O Senhor, nosso Deus, provou que eram mentirosos aqueles que o desacreditaram e tornou-o ilustre para sempre.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jac 1:12.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo falará com sabedoria e a sua língua proclamará a justiça!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sofre a tentação, porque, depois de ser provado, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 18:1-5\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlorum? Et ádvocans Jesus parvulum, státuit eum in médio eórum et dixit: Amen, dico vobis, nisi convérsi fuéritis et efficiámini sicut párvuli, non intrabitis in regnum cœlórum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlorum. Et qui suscéperit unum párvulum talem in nómine meo, me súscipit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 18:1-5\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, aproximaram-se de Jesus os discípulos, dizendo-lhe: «Qual pensais Vós que é o maior no reino dos céus?». E Jesus, havendo chamado um pequeno, colocou-o no meio deles e disse: «Em verdade vos digo: se vos não converteis e não vos tornais como os pequenos, não entrareis no reino dos céus. Todo aquele, pois, que se fizer pequeno, como este menino, esse é o maior no reino dos céus; e quem receber em meu nome um pequeno, como este, recebe-me a mim mesmo».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 9:17\u003c/I>\u003c/FONT>\u003cbr/>\nDesidérium páuperum exaudívit Dóminus: præparatiónem cordis eórum audívit auris tua.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 9:17\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor ouviu o desejo dos pobres; os seus ouvidos escutaram a pureza do seu coração.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAltáre tuum, Dómine, munéribus cumulamus oblatis: ut ejus nobis fiant supplicatione propitia, cujus nos donasti patrocínio adjuvári.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nCumulamos, Senhor, os vossos altares com dons e oblatas, a fim de que nos alcancem misericórdia pelas orações daquele que nos proporcionastes para nos auxiliar com seu patrocínio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 10:14\u003c/I>\u003c/FONT>\u003cbr/>\nSínite párvulos veníre ad me, et ne prohibuéritis eos: tálium est enim regnum Dei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 10:14\u003c/I>\u003c/FONT>\u003cbr/>\nDeixai aproximarem-se de mim as criancinhas e as não afasteis, pois delas é o reino de Deus.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSanctificáti, Dómine, salutári mystério: quǽsumus; ut, intercedénte sancto Josépho Confessóre tuo, ad majus semper proficiámus pietátis increméntum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSantificados, Senhor, com estes salutares mystérios, Vos rogamos que pela intercessão de S. José, vosso Confessor, permitais que aumentemos sempre cada vez mais a nossa piedade.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-28":{"date":"2026-08-28","title":"Santo Agostinho de Hipona, bispo, confessor e doutor","forms":[{"number":1,"title":"S. Augustini Episcopi et Confessoris et Ecclesiæ Doctoris Duplex vide Commune Doctorum Pontificium (Missa In medio) [Commune/C4a.txt]","winner":"Sancti/08-28.txt","rule":"vide C4a;\nGloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nAdésto supplicatiónibus nostris, omnípotens Deus: et, quibus fidúciam sperándæ pietátis indúlges, intercedénte beáto Augustíno Confessóre tuo atque Pontífice, consuétæ misericórdiæ tríbue benígnus efféctum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Hermetis Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui beátum Hermétem Mártyrem tuum virtúte constántiæ in passióne roborásti: ex ejus nobis imitatióne tríbue; pro amóre tuo próspera mundi despícere, et nulla ejus advérsa formidáre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOuvi benigno, ó Deus omnipotente, as nossas súplicas, e, visto que nos permitis confiarmos na vossa bondade, concedei-nos, pela intercessão do B. Agostinho, vosso Confessor e Pontífice, a graça de alcançarmos o efeito benigno da vossa habitual misericórdia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Hermes, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que fortalecestes o B. Hermes, vosso Mártir, com a virtude da constância no seu suplício, concedei-nos, pelo vosso amor, que, seguindo seu exemplo, desprezemos as prosperidades deste mundo e nunca temamos as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Timótheum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tim 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum imple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo a Timóteo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tm 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimo: Conjuro-te diante de Deus e de Jesus Cristo, que há-de julgar vivos e mortos na sua vinda e no seu reino, a que pregues a palavra; instes oportuna e inoportunamente; repreendas; supliques; e ameaces com toda a paciência e doutrina; pois virá tempo em que não suportarão a sã doutrina, mas, indo ao sabor dos seus desejos, procurarão para si muitos mestres, que lhes preguem o que os ouvidos gostam de escutar, e fechem os ouvidos à verdade, para os abrirem às fábulas. Tu, porém, vigia, trabalha em tudo, cumpre o ministério de evangelista e desempenha o teu ministério. Sê sóbrio. Pois quanto a mim sou como uma vítima já aspergida para o sacrifício. O tempo da minha morte já se aproxima. Pelejei o bom combate; acabei a vida; permaneci na fé. Não me falta mais do que esperar a coroa da justiça, que me está reservada, a qual o Senhor, como justo juiz, me dará no grande dia: e não somente a mim, mas também àqueles que amam a sua vinda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:21\u003c/I>\u003c/FONT>\u003cbr/>\nInvéni David servum meum, óleo sancto meo unxi eum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo falará com sabedoria e a sua língua proclamará a justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:21\u003c/I>\u003c/FONT>\u003cbr/>\nEncontrei o meu servo David e ungi-o com meu óleo sagrado. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Sois o sal da terra. Se o sal perde a força, com que salgará? Para nada mais presta, senão para se lançar fora e ser pisado pelos homens. Sois a luz do mundo. Uma cidade situada no cimo de um monte não pode ficar escondida. Nem se acende uma luz para a meter debaixo do alqueire, mas para a colocar no candeeiro, a fim de alumiar todos os que estão em casa. Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem vosso Pai, que está nos céus. Não penseis que vim abrogar a Lei ou os Profetas: não vim abrogar, mas aperfeiçoar; porque em verdade vos digo: até que passe o céu e a terra, nem um iota, nem um til se omitirá na Lei. Quem quer, pois, que transgrida, ainda um dos mais pequenos mandamentos, ou ensine os homens a violá-los, será chamado o menor no reino dos céus. Porém, quem os cumprir e ensinar será chamado grande no reino dos céus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti Augustíni Pontíficis tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Hermetis Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>acrifícium tibi, Dómine, laudis offérimus in tuórum commemoratióne Sanctórum: da, quǽsumus; ut, quod illis cóntulit glóriam, nobis prosit ad salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, que a piedosa oração de Santo Agostinho vosso Pontífice e Doutor, nos não abandone, e que por ela as nossas ofertas Vos sejam agradáveis e alcancemos benigna e continuamente a vossa misericórdia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Hermes, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os oferecemos, Senhor, em memória dos vossos Santos, este sacrifício de louvor; e, Vos imploramos, fazei que aquilo que lhe alcançou a glória sirva de proveito à nossa salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nUt nobis, Dómine, tua sacrifícia dent salútem: beátus Augustínus Póntifex tuus et Doctor egrégius, quǽsumus, precátor accédat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Hermetis Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>epleti, Dómine, benedictióne cœlésti, quǽsumus cleméntiam tuam: ut, intercedénte beáto Herméte Mártyre tuo, quæ humíliter gérimus, salúbriter sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Senhor, dignai-Vos conceder-nos que o B. Agostinho, vosso Pontífice e ilustre Doutor, seja nosso intercessor perante Vós, a fim de que este sacrifício nos alcance a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Hermes, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>aciados, Senhor, com a celestial bênção, invocamos a vossa clemência, a fim de que pela intercessão do B. Hermes, vosso Mártir, alcancemos os salutares efeitos do sacrifício, que humildemente celebramos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-29":{"date":"2026-08-29","title":"Degolação de São João Batista","forms":[{"number":1,"title":"In Decollatione S. Joannis Baptistæ Duplex vide Commune Unius Martyris non Pontificis (Missa In virtute) [Commune/C2a.txt]","winner":"Sancti/08-29.txt","rule":"ex C2a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:46-47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>oquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>oquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:46-47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>alava na presença dos reis sobre a vossa lei e não me envergonhava: meditava nos vossos mandamentos, que muito amei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor e cantar hinos em honra do vosso nome, ó Altíssimo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>alava na presença dos reis sobre a vossa lei e não me envergonhava: meditava nos vossos mandamentos, que muito amei.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSancti Joánnis Baptístæ Præcursóris et Martyris tui, quǽsumus, Dómine, veneránda festívitas: salutáris auxílii nobis præstet efféctum:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Sabinæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui inter cétera poténtiæ tuæ mirácula étiam in sexu frágili victóriam martýrii contulísti: concéde propítius; ut, qui beátæ Sabínæ Mártyris tuæ natalícia cólimus, per ejus ad te exémpla gradiámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, Vos rogamos, que a veneranda festividade de S. João Baptista, vosso Precursor e Mártir, nos alcance o efeito do vosso salutar auxílio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Sabinæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que entre outros milagres do vosso poder permitistes que o sexo frágil alcançasse a vitória do martírio, concedei-nos propício que, venerando o nascimento da vossa B. Mártir Sabina, caminhemos para Vós, imitando os seus exemplos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Jeremíæ Prophétæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 1:17-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Factum est verbum Dómini ad me, dicens: Accínge lumbos tuos, et surge, et lóquere ad Juda ómnia, quæ ego præcípio tibi. Ne formides a fácie eórum: nec enim timére te fáciam vultum eórum. Ego quippe dedi te hódie in civitátem munítam, et in colúmnam férream, et in murum æreum, super omnem terram, régibus Juda, princípibus ejus, et sacerdótibus, et pópulo terræ. Et bellábunt advérsum te, et non prævalebunt: quia ego tecum sum, ait Dóminus, ut líberem te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Profeta Jeremias.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 1:17-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, o Senhor falou-me e disse-me: «Cinge os teus rins, levanta-te e diz à Judeia tudo quanto te ordenar. Não temas aparecer diante deles, porque farei que tu não tenhas medo. Formei-te hoje como uma cidade forte, como uma coluna de ferro e como um muro de bronze, em toda a terra, diante dos reis de Judá, dos seus príncipes, dos seus sacerdotes e do seu povo. Eles combaterão contra ti, mas não triunfarão, pois estou contigo para te livrar», diz o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Osee 14:6\u003c/I>\u003c/FONT>\u003cbr/>\nJustus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Para publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Oz 14:6\u003c/I>\u003c/FONT>\u003cbr/>\nO justo germinará, como o lírio, e florescerá eternamente perante o Senhor. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Marcum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 6:17-29\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Misit Heródes, ac ténuit Joánnem, et vinxit eum in cárcere propter Herodíadem, uxorem Philíppi fratris sui, quia dúxerat eam. Dicebat enim Joánnes Heródi: Non licet tibi habére uxórem fratris tui. Heródias autem insidiabátur illi, et volébat occídere eum, nec póterat. Heródes enim metuébat Joánnem, sciens eum virum justum et sanctum: et custodiébat eum, et audíto eo multa faciébat, et libénter eum audiébat. Et cum dies opportúnus accidísset, Heródes natális sui cœnam fecit princípibus et tribúnis et primis Galilææ. Cumque introísset fília ipsíus Herodíadis, et saltásset, et placuísset Heródi simúlque recumbéntibus; rex ait puéllæ: Pete a me, quod vis, et dabo tibi. Et jurávit illi: Quia quidquid petiéris dabo tibi, licet dimídium regni mei. Quæ cum exiísset, dixit matri suæ: Quid petam? At illa dixit: Caput Joánnis Baptístæ. Cumque introísset statim cum festinatióne ad regem, petívit dicens: Volo, ut protínus des mihi in disco caput Joánnis Baptístæ. Et contristátus est rex: propter jusjurándum et propter simul discumbéntes nóluit eam contristáre: sed misso spiculatóre, præcépit afférri caput ejus in disco. Et decollávit eum in cárcere. Et áttulit caput ejus in disco: et dedit illud puéllæ, et puella dedit matri suæ. Quo audíto, discípuli ejus venérunt et tulérunt corpus ejus: et posuérunt illud in monuménto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Marcos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 6:17-29\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, mandou Herodes prender João, ligá-lo e metê-lo no cárcere, para agradar a Herodíade, mulher de Filipe, seu irmão, a qual ele havia desposado. Ora, João dizia a Herodes: «Não te é lícito tomar a mulher de teu irmão». Por isso Herodíade armava-lhe ciladas e queria matá-lo, mas não podia; pois Herodes temia João, sabendo que era homem justo e santo. Contudo Herodes conservava-o em custódia, ainda que fizesse muitas coisas inspirado pelos seus conselhos e até, espontaneamente, o ouvisse. Chegou, porém, um dia favorável o dia do aniversário do nascimento de Herodes em que este oferecia um banquete aos grandes, aos tribunos e aos príncipes da Galileia. Então, entrou na sala a filha de Herodíade, dançando e agradando a Herodes e aos presentes. Disse-lhe o rei: «Pede o que quiseres que te darei». E fez-lhe um juramento: «Tudo o que me pedires te darei, ainda que seja metade do meu reino». Ouvindo ela isto, saiu e perguntou à mãe: «Que pedirei eu?». A mãe respondeu-lhe: «A cabeça de João Baptista». Logo, entrou na sala, apressadamente, e, indo ao pé do rei, fez-lhe o pedido nestes termos: «Quero que me dês, já, em um prato, a cabeça de João Baptista». Contristou-se muito o rei; mas, por causa do seu juramento e dos convivas, não quis contrariá-la enviando um dos seus guardas com a ordem de lhe trazer a cabeça de João Baptista, em um prato. O guarda cortou-lhe a cabeça na prisão, colocou-a em um prato, deu-a à filha de Herodíade e esta deu-a a sua mãe. Ouvindo isto, os discípulos vieram, levaram o seu corpo e colocaram-no em um túmulo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nIn virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nO justo, Senhor, alegrar-se-á com vosso poder e rejubilará, vendo-se salvo por Vós: concedestes-lhe o desejo do seu coração.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nMúnera, quæ tibi, Dómine, pro sancti Martyris tui Joánnis Baptístæ passióne deférimus: quǽsumus; ut ejus obténtu nobis profíciant ad salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Sabinæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>óstias tibi, Dómine, beátæ Sabínæ Mártyris tuæ dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos apresentamos, Senhor, estas oblatas em honra dos sofrimentos do vosso santo Mártir João Baptista, e, Vos suplicamos, fazei pelos seus méritos que sirvam de proveito à nossa salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Sabinæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ceitai benignamente, Senhor, as hóstias que Vos oferecemos pelos méritos da B. e Mártir Sabina, e dignai-Vos permitir que ela nos sirva de perpétuo auxílio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:4\u003c/I>\u003c/FONT>\u003cbr/>\nPosuísti, Dómine, in cápite ejus corónam de lápide pretióso.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:4\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, colocastes na sua cabeça uma coroa de pedras preciosas.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nCónferat nobis, Dómine, sancti Joánnis Baptístæ sollémnitas: ut et magnífica sacraménta, quæ súmpsimus, significáta venerémur, et in nobis pótius édita gaudeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Sabinæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ivíni múneris largitáte satiáti, quǽsumus, Dómine, Deus noster: ut, intercedénte beáta Sabína Vírgine et Mártyre tua, in ejus semper participatióne vivámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nQue a solenidade de S. João Baptista, Senhor, nos alcance a graça de venerarmos nos augustos sacramentos, que recebemos, o que as aparências dos mesmos significam; e, mais ainda, de gozarmos a alegria de os haver recebido.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Sabinæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>aciados com a liberalidade do dom divino, ó Senhor, nosso Deus, Vos suplicamos pela intercessão da B. Sabina, vossa Mártir, que durante a nossa vida comparticipemos sempre deste dom divino.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-30":{"date":"2026-08-30","title":"XIV Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XIV Post Pentecosten V. Augusti\tSemiduplex","winner":"Tempora/Pent14-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 83:10-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>rotéctor noster, áspice, Deus, et réspice in fáciem Christi tui: quia mélior est dies una in átriis tuis super mília.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Quam dilécta tabernácula tua, Dómine virtútum! Concupíscit, et déficit ánima mea in átria Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>rotéctor noster, áspice, Deus, et réspice in fáciem Christi tui: quia mélior est dies una in átriis tuis super mília\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 83:10-11\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, nosso protector, olhai para nós e fitai a face do vosso Cristo: É melhor passar um só dia nos vossos átrios do que mil em outros lugares.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nComo são amáveis os vossos tabernáculos, Senhor dos exércitos! Minha alma suspira pelos átrios do Senhor e desfalece de saudade ao pensar neles.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, nosso protector, olhai para nós e fitai a face do vosso Cristo: É melhor passar um só dia nos vossos átrios do que mil em outros lugares.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nCustódi, Dómine, quǽsumus, Ecclésiam tuam propitiatióne perpétua: et quia sine te lábitur humána mortálitas; tuis semper auxíliis et abstrahátur a nóxiis et ad salutária dirigátur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, guardai misericordiosamente a vossa Igreja para sempre; e, visto que sem Vós a natureza humana, sujeita à morte, não pode subsistir, dignai-Vos com vosso perpétuo auxílio preservá-la de tudo o que lhe pode produzir algum mal e conduzi-la a tudo o que seja salutar à sua salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Gálatas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gal 5:16-24\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Spíritu ambuláte, et desidéria carnis non perficiétis. Caro enim concupíscit advérsus spíritum, spíritus autem advérsus carnem: hæc enim sibi ínvicem adversántur, ut non quæcúmque vultis, illa faciátis. Quod si spíritu ducímini, non estis sub lege. Manifésta sunt autem ópera carnis, quæ sunt fornicátio, immundítia, impudicítia, luxúria, idolórum sérvitus, venefícia, inimicítiæ, contentiónes, æmulatiónes, iræ, rixæ, dissensiónes, sectæ, invídiæ, homicídia, ebrietátes, comessatiónes, et his simília: quæ prædíco vobis, sicut prædíxi: quóniam, qui talia agunt, regnum Dei non consequántur. Fructus autem Spíritus est: cáritas, gáudium, pax, patiéntia, benígnitas, bónitas, longanímitas, mansuetúdo, fides, modéstia, continéntia, cástitas. Advérsus hujúsmodi non est lex. Qui autem sunt Christi, carnem suam crucifixérunt cum vítiis et concupiscéntiis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Gálatas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gl 5:16-24\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Andai guiados pelo espírito, e não tereis os desejos da carne; Pois a carne tem desejos contrários aos do espírito, e o espírito tem desejos contrários aos da carne. São opostos entre si. Deste modo não podeis fazer tudo quanto desejais. Se obedecerdes ao espírito, não estareis sob a lei. Ora as obras da carne são bem manifestas, quais são: a cópula, a imundícia, a impudicícia, a luxúria, a idolatria, os envenenamentos, as inimizades, as contendas, as emulações, as iras, as discórdias, as discussões, as heresias, as invejas, os homicídios, a embriaguez, as comezanas e ainda outras cousas semelhantes. Eu vos declaro \u003cFONT SIZE='1' COLOR=\"red\">como já vo-lo disse\u003c/FONT> que aqueles que cometem tais cousas não entrarão no reino de Deus. Porém, os frutos do espírito são os seguintes: a caridade, a alegria, a paz, a paciência, a mansidão, a bondade, a longanimidade, a doçura, a fé, a modéstia, a continência e a castidade. Contra estes frutos não há lei a opor. Aqueles que são de Cristo crucificaram a sua carne, as suas paixões e os seus desejos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 117:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confidére in Dómino, quam confidére in hómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Bonum est speráre in Dómino, quam speráre in princípibus. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 94:1.\u003c/I>\u003c/FONT>\u003cbr/>\nVeníte, exsultémus Dómino, jubilémus Deo, salutári nostro. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 117:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nÉ melhor confiar no Senhor do que nos homens.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> É melhor esperar em Deus do que nos príncipes. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 94:1\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vinde, cantemos com alegria ao Senhor, exultemos jubilosamente em Deus, nosso Salvador. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 6:24-33\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Nemo potest duóbus dóminis servíre: aut enim unum ódio habébit, et álterum díliget: aut unum sustinébit, et álterum contémnet. Non potéstis Deo servíre et mammónæ. Ideo dico vobis, ne sollíciti sitis ánimæ vestræ, quid manducétis, neque córpori vestro, quid induámini. Nonne ánima plus est quam esca: et corpus plus quam vestiméntum? Respícite volatília cœli, quóniam non serunt neque metunt neque cóngregant in hórrea: et Pater vester cœléstis pascit illa. Nonne vos magis pluris estis illis? Quis autem vestrum cógitans potest adjícere ad statúram suam cúbitum unum? Et de vestiménto quid sollíciti estis? Consideráte lília agri, quómodo crescunt: non labórant neque nent. Dico autem vobis, quóniam nec Sálomon in omni glória sua coopértus est sicut unum ex istis. Si autem fænum agri, quod hódie est et cras in clíbanum míttitur, Deus sic vestit: quanto magis vos módicæ fídei? Nolíte ergo sollíciti esse, dicéntes: Quid manducábimus aut quid bibémus aut quo operiémur? Hæc enim ómnia gentes inquírunt. Scit enim Pater vester, quia his ómnibus indigétis. Quǽrite ergo primum regnum Dei et justítiam ejus: et hæc ómnia adjiciéntur vobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 6:24-33\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Ninguém pode servir a dois senhores, pois ou há-de odiar um e amar o outro, ou respeitar este e desprezar aquele. Não podeis servir a Deus e às riquezas. Eis porque digo: não vos inquieteis pelas cousas da vossa vida, se tereis o que comer; nem do vosso corpo, se tereis o que vestir. Porventura não é a vida mais do que o alimento e o corpo mais do que o vestido? Reparai nas aves do céu: nem semeiam, nem ceifam, nem arrecadam nos celeiros; contudo o Pai celestial sustenta-as. Acaso não valeis mais do que elas? Qual de vós será capaz, ainda que empregue todas as diligências, de acrescentar um côvado à sua altura? E, quanto ao vestir, porque vos inquietais? Reparai como os lírios dos campos crescem! Eles não trabalham, nem fiam; contudo nem Salomão, apesar de toda sua magnificência, teve um vestido como eles. Ora, se Deus veste assim as ervas dos campos, que hoje existem e amanhã serão lançadas no fogo, quanto mais terá cuidado de vós, homens de pouca fé! Não vos inquieteis, pois, dizendo: «Que havemos de comer e de beber; e como nos vestiremos?». Os pagãos é que têm cuidados com estas cousas. Vosso Pai celestial sabe bem aquilo de que careceis. Procurai primeiramente o reino de Deus e a sua justiça, e todas estas cousas vos serão dadas».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 33:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nImmíttet Angelus Dómini in circúitu timéntium eum, et erípiet eos: gustáte et vidéte, quóniam suávis est Dóminus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 33:8 - 9.\u003c/I>\u003c/FONT>\u003cbr/>\nO Anjo do Senhor circundará aqueles que temem o Senhor e livrá-los-á. Provai e vede como o Senhor é bom!\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nConcéde nobis, Dómine, quǽsumus, ut hæc hóstia salutáris et nostrórum fiat purgátio delictórum, et tuæ propitiátio potestátis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nConcedei-nos, Senhor, Vos suplicamos, que esta salutar hóstia nos purifique das nossas faltas e nos torne propício o vosso poder.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 6:33\u003c/I>\u003c/FONT>\u003cbr/>\nPrimum quǽrite regnum Dei, et ómnia adjiciéntur vobis, dicit Dóminus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 6:33\u003c/I>\u003c/FONT>\u003cbr/>\nProcurai primeiramente o reino de Deus, e tudo vos será dado por acréscimo, diz o Senhor.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPuríficent semper et múniant tua sacraménta nos, Deus: et ad perpétuæ ducant salvatiónis efféctum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, ó Deus, que os vossos sacramentos nos purifiquem e fortifiquem sempre, e nos façam gozar a salvação eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2026-08-31":{"date":"2026-08-31","title":"São Raimundo Nonato, confessor","forms":[{"number":1,"title":"S. Raymundi Nonnati Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/08-31.txt","rule":"vide C5\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui in liberándis fidélibus tuis ab impiórum captivitáte beátum Raymúndum Confessórem tuum mirábilem effecísti: ejus nobis intercessióne concéde; ut, a peccatórum vínculis absolúti, quæ tibi sunt plácita, líberis méntibus exsequámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que ao B. Raimundo, vosso Confessor, tornastes admirável na dedicação com que libertava os vossos fiéis do cativeiro dos ímpios, concedei-nos pela sua intercessão que, livres dos vínculos dos pecados, cumpramos com liberdade de espírito o que Vos é agradável.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPelos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]}}};
